@media (max-width: 767px),
(pointer: coarse) {

  html,
  body {
    height: 100%;
    height: 100dvh;
    min-height: 100dvh;
    overflow: hidden;
    background: var(--theia-editor-background);
  }

  /* Monaco quick input lives on `document.body`; keep it above side sheets / backdrops (~10k). */
  #quick-input-container {
    z-index: 2147483000 !important;
  }

  /* Hide desktop menubar only in one-column mobile shell (bottom activity strip replaces it). */
  #theia-app-shell.theia-mod-mobile-one-column #theia-top-panel .lm-MenuBar,
  #theia-app-shell.theia-mod-mobile-one-column #theia-top-panel [id='theia:menubar'] {
    display: none !important;
  }

  /* Terminal and Agent live in the bottom activity bar on mobile; keep settings in the top bar. */
  #theia-app-shell.theia-mod-mobile-one-column .theia-workbench-right-controls .theia-workbench-nav-btn.theia-workbench-in-mobile-bottom-bar {
    display: none !important;
  }

  #theia-app-shell.theia-mod-mobile-one-column .theia-workbench-right-controls {
    position: relative;
    z-index: 2;
    pointer-events: auto;
  }

  #theia-app-shell.theia-ApplicationShell:not(.theia-mod-mobile-one-column) {
    box-sizing: border-box;
    padding-top: env(safe-area-inset-top, 0px);
    padding-right: env(safe-area-inset-right, 0px);
    /* `--theia-mobile-keyboard-inset` is set by MobileKeyboardHelper from
       window.visualViewport so the layout shrinks above the virtual keyboard.
       Bottom navigation and status chrome are hidden while the inset is active. */
    padding-bottom: calc(env(safe-area-inset-bottom, 0px) + var(--theia-mobile-keyboard-inset, 0px));
    padding-left: env(safe-area-inset-left, 0px);
  }

  /* Match workbench-cursor-typography .mac/.windows/.linux overrides. */
  :root,
  .mac,
  .windows,
  .linux {
    /* Same height as `#theia-app-shell.theia-mod-mobile-one-column` bottom strip.
       Defined here so `document.body` descendants (e.g. `.theia-notifications-overlay`)
       inherit it — shell-only variables do not apply outside `#theia-app-shell`. */
    --theia-mobile-bottom-bar-height: 64px;
    --theia-mobile-status-chrome-height: calc(var(--theia-statusBar-height, 34px) + env(safe-area-inset-bottom, 0px));
    /* Bottom activity bar + status strip reserved while the keyboard is closed. */
    --theia-mobile-bottom-chrome-reserved: calc(var(--theia-mobile-bottom-bar-height, 56px) + var(--theia-mobile-status-chrome-height, 34px));
    /* Bottom activity bar + status + virtual keyboard (`MobileKeyboardHelper`) + home indicator. */
    --theia-mobile-bottom-chrome-stack: calc(var(--theia-mobile-bottom-chrome-reserved, 0px) + var(--theia-mobile-keyboard-inset, 0px) + env(safe-area-inset-bottom, 0px));
    /* Keyboard-only lift when the bottom chrome is hidden (Agents landing / active transcript). */
    --theia-mobile-keyboard-lift: calc(var(--theia-mobile-keyboard-inset, 0px) + env(safe-area-inset-bottom, 0px));
    --theia-ui-font-size1: 15px;
    --theia-content-font-size: 15px;
    --theia-content-line-height: 24px;
    --theia-code-font-size: 14px;
    --theia-code-line-height: 21px;
    --theia-ui-padding: 10px;
    --theia-icon-size: 18px;
    --theia-ui-icon-font-size: 18px;
    --theia-statusBar-font-size: 13px;
    --theia-statusBar-height: 34px;
    --theia-private-menubar-height: 40px;
    --theia-private-horizontal-tab-height: 40px;
    --theia-horizontal-toolbar-height: 40px;
    --theia-private-sidebar-tab-width: 52px;
    --theia-scrollbar-width: 12px;
    --theia-scrollbar-rail-width: 12px;
  }

  .theia-app-activity-bar-row {
    --theia-horizontal-toolbar-height: 44px;
    --theia-private-sidebar-tab-height: 32px;
    --theia-private-sidebar-icon-size: 18px;
    --theia-private-sidebar-tab-padding-top-and-bottom: 8px;
    --theia-private-sidebar-tab-padding-left-and-right: 10px;
    min-height: 44px;
  }

  .lm-TabBar.theia-app-sides[data-orientation="horizontal"] {
    min-height: 44px;
  }

  .lm-TabBar.theia-app-sides[data-orientation="horizontal"] .theia-tabBar-tab-row {
    min-height: 44px;
  }

  .theia-workbench-nav-btn:not(.theia-workbench-account-btn):not(.theia-workbench-history-nav-btn) {
    min-width: 40px;
    min-height: 36px;
    width: auto;
