  }

  #theia-statusBar {
    overflow-x: auto;
    overflow-y: hidden;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-x;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }

  #theia-statusBar::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
  }

  #theia-statusBar .theia-statusBar-track {
    min-height: var(--theia-statusBar-height);
    width: max-content;
    min-width: 100%;
    flex-wrap: nowrap;
