  .theia-TreeNodeContent {
    padding-top: 6px;
    padding-bottom: 6px;
  }

  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab {
    min-width: 44px;
    padding: 0 12px;
    scroll-snap-align: start;
  }

  /* Tab close (×): desktop renders at 16px with 2px padding → ~20px hit area,
     well below WCAG 2.5.5. Expand to 28×28 on the current tab so it can be
     hit reliably with a fingertip without growing the tab row height. */
  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab.lm-mod-closable>.lm-TabBar-tabCloseIcon,
  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab.theia-mod-pinned>.lm-TabBar-tabCloseIcon,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab.lm-mod-closable>.lm-TabBar-tabCloseIcon,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab.theia-mod-pinned>.lm-TabBar-tabCloseIcon {
    width: 28px;
    height: 28px;
    padding: 6px;
    line-height: 16px;
    margin-left: 6px;
    font-size: 16px;
    box-sizing: content-box;
  }

  /* On touch-only devices, `:hover` never fires; reveal the close icon on the
     current tab unconditionally so the user has a way to close it. Dynamic
     tabs (`.dynamic-tabs`) still keep the desktop behaviour of hiding it. */
  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"]:not(.dynamic-tabs) .lm-TabBar-tab.lm-mod-closable.lm-mod-current>.lm-TabBar-tabCloseIcon,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"]:not(.dynamic-tabs) .lm-TabBar-tab.lm-mod-closable.lm-mod-current>.lm-TabBar-tabCloseIcon {
    display: inline-block;
  }

  /*-----------------------------------------------------------------------------
  || Breadcrumbs. Desktop row is 22px tall — below WCAG 2.5.5; the dropdown
  || picker is 300×200 fixed and clips off-screen on a phone.
  ||----------------------------------------------------------------------------*/
  .theia-breadcrumbs {
    height: 36px;
    padding: 0 4px;
  }

  .theia-breadcrumbs .theia-breadcrumb-item {
    padding: 0 6px;
    min-height: 36px;
  }

  .theia-breadcrumbs .theia-breadcrumb-item:not(:last-of-type)::after {
    font-size: var(--theia-ui-font-size3, 14px);
  }

  /* Pin the breadcrumb picker to the viewport so it doesn't run off the edge. */
  .theia-breadcrumbs-popup {
    width: min(calc(100vw - 16px), 480px) !important;
    max-width: calc(100vw - 16px) !important;
    max-height: 60vh !important;
    border-radius: 8px;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.35);
    overflow: auto;
    -webkit-overflow-scrolling: touch;
  }

  .theia-breadcrumbs-popup ul li {
    min-height: 40px;
    padding: 8px 12px;
  }

  /*-----------------------------------------------------------------------------
  || Monaco editor floating widgets (hover, parameter hints, suggest). Monaco
  || positions them relative to the cursor with no viewport clamp — on a phone
  || they routinely overflow the viewport horizontally and clip vertically.
  || Constrain to viewport with an internal scroll for long content.
  ||----------------------------------------------------------------------------*/
  .monaco-editor .monaco-hover,
  .monaco-editor-hover.monaco-hover {
    max-width: calc(100vw - 16px) !important;
    max-height: 50vh !important;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    font-size: var(--theia-ui-font-size1);
    line-height: 1.4;
  }

  .monaco-editor .parameter-hints-widget {
    max-width: calc(100vw - 16px) !important;
    max-height: 40vh !important;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
  }

  .monaco-editor .suggest-widget {
    max-width: calc(100vw - 16px) !important;
    max-height: 50vh !important;
  }

  /* Flex child of `.theia-tabBar-tab-row` must shrink below tab min-content so overflow-x applies here. */
  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container {
    min-width: 0;
  }

  /* Same idea as `.theia-mobile-bottom-activity-bar`: row must not shrink so `scrollWidth` exceeds
     the viewport and horizontal pan scrolls the strip with native inertia. */
  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content {
    flex-shrink: 0;
    min-width: min-content;
    flex-wrap: nowrap;
  }

  /* Horizontal pan only; hide scrollbars so the tab row keeps a single compact height (no rail
     under the tabs). Native overflow scrolling stays available for touch / trackpad.
     Selectors omit `.ps` because on narrow viewports PerfectScrollbar is not used (see ScrollableTabBar). */
  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container {
    touch-action: pan-x;
    user-select: none;
    -webkit-user-select: none;
    overscroll-behavior-x: contain;
    scroll-snap-type: x proximity;
    overflow-x: auto !important;
    overflow-y: hidden !important;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }

  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container::-webkit-scrollbar,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
  }

  #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container>.ps__rail-x,
  #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container>.ps__rail-x {
    display: none !important;
  }

  @media (prefers-reduced-motion: reduce) {

    #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container,
    #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-content-container {
      scroll-snap-type: none;
    }

    #theia-main-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab,
    #theia-bottom-content-panel .lm-TabBar[data-orientation="horizontal"] .lm-TabBar-tab {
      scroll-snap-align: none;
    }
  }

  .theia-sidepanel-toolbar {
    min-height: 44px;
  }

  .theia-sidepanel-toolbar .lm-TabBar-toolbar .item>div {
    min-width: 36px;
    min-height: 36px;
