  /* Full viewport height under the top safe-area only; menubar strip is not reserved so the sheet gains vertical space. */
  top: env(safe-area-inset-top, 0px) !important;
  /* Keep sheet content above the fixed bottom navigation and status chrome. */
  bottom: calc(var(--theia-mobile-bottom-chrome-reserved, 0px) + var(--theia-mobile-keyboard-inset, 0px)) !important;
  left: 0 !important;
  right: 0 !important;
  width: 100vw !important;
  max-width: 100% !important;
  height: auto !important;
  box-sizing: border-box;
  border-top-left-radius: 0;
  border-top-right-radius: 0;
  overflow: hidden;
  overflow: clip;
  clip-path: inset(0);
  -webkit-clip-path: inset(0);
  isolation: isolate;
  box-shadow: 0 -10px 36px rgba(0, 0, 0, 0.45);
  background: var(--theia-sideBar-background, var(--theia-editor-background));
  transition:
    transform 220ms cubic-bezier(.2, .8, .2, 1),
