  -webkit-tap-highlight-color: transparent;
}

@supports (backdrop-filter: blur(8px)) or (-webkit-backdrop-filter: blur(8px)) {
  .theia-mobile-sheet-backdrop {
    background: rgba(0, 0, 0, 0.14);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

.theia-mobile-sheet-backdrop.theia-mod-visible {
  opacity: 1;
  /* Decorative only: body-level backdrop (9500) stacks above #theia-app-shell (0) and would
     close side sheets on the first in-panel touch if this were auto. */
  pointer-events: none;
}

/* Agent-first bottom bar (Lumino widget in the shell layout, pinned with `position: fixed` in
   `.theia-mod-mobile-one-column`). Visually fused with the status bar below: shares its background/foreground tokens. When the
   browser supports `backdrop-filter`, we replace the opaque background with a translucent token
   + blur so the bar feels like a floating glass surface above the editor — matching the same
   frosted look applied to side sheets. */
.theia-mobile-bottom-activity-bar {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  justify-content: stretch;
  align-items: stretch;
  min-height: var(--theia-mobile-bottom-bar-height, 56px);
  max-height: var(--theia-mobile-bottom-bar-height, 56px);
  min-width: 0;
  max-width: 100%;
  padding: 4px 0;
  background: var(--theia-statusBar-background);
  color: var(--theia-statusBar-foreground);
  border-top: 1px solid var(--theia-statusBar-border, transparent);
  box-sizing: border-box;
  gap: 0;
  overflow-x: hidden;
  overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  touch-action: manipulation;
}

@supports (backdrop-filter: blur(12px)) or (-webkit-backdrop-filter: blur(12px)) {
  .theia-mobile-bottom-activity-bar {
    background: color-mix(in srgb,
        var(--theia-statusBar-background) 72%,
        transparent);
    -webkit-backdrop-filter: blur(16px) saturate(140%);
    backdrop-filter: blur(16px) saturate(140%);
  }
}

.theia-mobile-bottom-activity-bar::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

.theia-mobile-bottom-activity-btn {
  flex: 1 1 0;
  min-width: 0;
  margin: 0;
  padding: 5px 4px;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  position: relative;
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 120ms ease, color 120ms ease;
}

.theia-mobile-bottom-activity-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  flex-shrink: 0;
  box-sizing: border-box;
}

.theia-mobile-bottom-activity-icon::before {
  font-size: 20px;
  line-height: 1;
  display: block;
}

.theia-mobile-bottom-activity-label {
  font-size: 11px;
  line-height: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  flex-shrink: 0;
}

.theia-mobile-bottom-activity-btn:hover:not(.theia-mod-unavailable):not(.theia-mod-active) {
  color: var(--theia-statusBar-foreground);
  background: var(--theia-statusBarItem-hoverBackground, rgba(255, 255, 255, 0.12));
}

.theia-mobile-bottom-activity-btn.theia-mod-active {
  color: var(--theia-statusBar-foreground);
}

.theia-mobile-bottom-activity-btn.theia-mod-active .theia-mobile-bottom-activity-icon {
  background: var(--theia-statusBarItem-activeBackground, var(--theia-statusBarItem-hoverBackground, rgba(255, 255, 255, 0.18)));
  color: var(--theia-statusBar-foreground);
}

.theia-mobile-bottom-activity-btn.theia-mod-active::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 3px;
  border-radius: 0 0 3px 3px;
  background: var(--theia-statusBar-foreground);
}

.theia-mobile-bottom-activity-btn.theia-mod-unavailable {
  opacity: var(--theia-mod-disabled-opacity, 0.4);
  cursor: default;
}

/* Edge swipe targets (body children).
   Bottom follows reserved chrome + keyboard inset so zones stay above the keyboard. */
.theia-mobile-edgeSwipeZone {
  position: fixed;
  top: calc(env(safe-area-inset-top, 0px) + var(--theia-private-menubar-height, 40px));
  bottom: calc(var(--theia-mobile-bottom-chrome-reserved, 0px) + var(--theia-mobile-keyboard-inset, 0px));
  width: 20px;
  z-index: 9650;
  touch-action: none;
}

.theia-mobile-edgeSwipeZone-left {
  left: 0;
}

.theia-mobile-edgeSwipeZone-right {
  right: 0;
}

/*-----------------------------------------------------------------------------
| Mobile first-launch onboarding overlay (see
| `mobile-onboarding-tutorial-contribution.ts`).
|
| The overlay covers the viewport at a higher z-index than the side sheets
| (9600) but its backdrop & spotlight have `pointer-events: none` so the
| underlying gesture (left-edge swipe, tap on Agent, …) being taught can still
| be performed. The tooltip and its buttons opt back in to pointer events.
|-----------------------------------------------------------------------------*/

.theia-mobile-onboarding-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  pointer-events: none;
  font-family: var(--theia-ui-font-family);
  color: var(--theia-foreground);
}

.theia-mobile-onboarding-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.72);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  animation: theia-mobile-onboarding-fade-in 180ms ease-out both;
}

.theia-mobile-onboarding-spotlight {
  position: absolute;
  border-radius: 14px;
  box-shadow:
    0 0 0 2px var(--theia-focusBorder, rgba(120, 200, 255, 0.95)),
    0 0 0 9999px rgba(0, 0, 0, 0.55),
    0 12px 32px rgba(0, 0, 0, 0.35);
  transition: top 220ms ease, left 220ms ease, width 220ms ease, height 220ms ease;
  pointer-events: none;
}

/* The spotlight uses a giant ring shadow that visually replaces the backdrop;
   hide the backdrop element while a spotlight is shown so the two don't compound.
   Driven by `theia-mod-has-spotlight`, toggled from the contribution — reliable across
   browsers, unlike matching against the spotlight's inline `display` style. */
.theia-mobile-onboarding-overlay.theia-mod-has-spotlight .theia-mobile-onboarding-backdrop {
  display: none;
}

.theia-mobile-onboarding-demo {
  position: absolute;
  pointer-events: none;
}

.theia-mobile-onboarding-demo.theia-mod-swipe-right {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--theia-editorWidget-foreground, var(--theia-foreground));
}

.theia-mobile-onboarding-finger {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.25), 0 6px 18px rgba(0, 0, 0, 0.35);
  flex: 0 0 32px;
  animation: theia-mobile-onboarding-swipe 1600ms ease-in-out infinite;
}

.theia-mobile-onboarding-demo .theia-mobile-onboarding-arrow {
  font-size: 22px;
  opacity: 0.85;
  animation: theia-mobile-onboarding-arrow-fade 1600ms ease-in-out infinite;
}

.theia-mobile-onboarding-demo.theia-mod-tap .theia-mobile-onboarding-pulse {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.25);
  box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.85);
  animation: theia-mobile-onboarding-tap 1400ms ease-out infinite;
}

@keyframes theia-mobile-onboarding-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes theia-mobile-onboarding-swipe {
  0% {
    transform: translateX(0);
    opacity: 0.0;
  }

  15% {
    opacity: 1.0;
  }

  85% {
    transform: translateX(160px);
    opacity: 1.0;
  }

  100% {
    transform: translateX(160px);
    opacity: 0.0;
  }
}

@keyframes theia-mobile-onboarding-arrow-fade {

  0%,
  20% {
    opacity: 0;
    transform: translateX(-4px);
  }

  60% {
    opacity: 1;
    transform: translateX(0);
  }

  100% {
    opacity: 0;
    transform: translateX(6px);
  }
}

@keyframes theia-mobile-onboarding-tap {
  0% {
    transform: scale(0.6);
    box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.55);
  }

  70% {
    transform: scale(1.15);
    box-shadow: 0 0 0 18px rgba(255, 255, 255, 0);
  }

  100% {
    transform: scale(0.6);
    box-shadow: 0 0 0 0 rgba(255, 255, 255, 0);
  }
}

.theia-mobile-onboarding-tooltip {
  position: absolute;
  pointer-events: auto;
  max-width: min(360px, calc(100vw - 24px));
  width: calc(100vw - 24px);
  background: var(--theia-editorWidget-background, var(--theia-sideBar-background, #2b2b2b));
  color: var(--theia-editorWidget-foreground, var(--theia-foreground));
  /* A hairline of light gives the card a visible edge on dark themes, where its surface
     colour is nearly identical to the panels behind it; the ring + drop shadow lift it
     clearly off the workbench so it never looks fused with the content underneath. */
  border: 1px solid var(--theia-editorWidget-border, rgba(255, 255, 255, 0.14));
  border-radius: 14px;
  padding: 16px 16px 12px;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.06),
    0 24px 56px rgba(0, 0, 0, 0.62);
  animation: theia-mobile-onboarding-fade-in 220ms ease-out both;
  box-sizing: border-box;
}

.theia-mobile-onboarding-tooltip.theia-mod-place-top {
  /* tooltip above target */
}

.theia-mobile-onboarding-tooltip.theia-mod-place-bottom {
  /* tooltip below target */
}

.theia-mobile-onboarding-tooltip.theia-mod-place-center {
  /* centered, no anchor */
}

.theia-mobile-onboarding-progress {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--theia-descriptionForeground);
  margin-bottom: 4px;
}

.theia-mobile-onboarding-title {
  font-size: 17px;
  font-weight: 600;
  margin: 0 0 6px 0;
  line-height: 1.25;
}

.theia-mobile-onboarding-body {
  font-size: 14px;
  line-height: 20px;
  margin: 0 0 14px 0;
  color: var(--theia-foreground);
}

.theia-mobile-onboarding-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.theia-mobile-onboarding-nav {
  display: flex;
  gap: 8px;
}

.theia-mobile-onboarding-dismiss {
  display: flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
}

.theia-mobile-onboarding-btn.theia-mod-remind {
  color: var(--theia-descriptionForeground);
  padding: 0 10px;
}

.theia-mobile-onboarding-btn {
  appearance: none;
  -webkit-appearance: none;
  min-height: 40px;
  padding: 0 16px;
  border-radius: 10px;
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  background: transparent;
  color: var(--theia-foreground);
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.theia-mobile-onboarding-btn.theia-mod-skip {
  color: var(--theia-descriptionForeground);
}

.theia-mobile-onboarding-btn.theia-mod-back {
  border-color: var(--theia-panel-border, transparent);
  background: var(--theia-button-secondaryBackground, transparent);
  color: var(--theia-button-secondaryForeground, var(--theia-foreground));
}

.theia-mobile-onboarding-btn.theia-mod-next {
  background: var(--theia-button-background, #0e639c);
  color: var(--theia-button-foreground, #fff);
}

.theia-mobile-onboarding-btn:hover,
.theia-mobile-onboarding-btn:focus-visible {
  filter: brightness(1.08);
  outline: none;
}

.theia-mobile-onboarding-btn:active {
  filter: brightness(0.95);
}

/* Wider screens that still match the mobile media query (e.g. 600 px tablets in portrait)
   shrink the tooltip to a card width centered in the viewport. */
@media (min-width: 480px) and (max-width: 767px),
(min-width: 480px) and (pointer: coarse) {
  .theia-mobile-onboarding-tooltip {
    width: min(420px, calc(100vw - 48px));
  }
}

/*-----------------------------------------------------------------------------
| Code keyboard accessory bar.
| Floating row with Tab / Esc / arrows / brackets shown above the virtual
| keyboard while a Monaco editor textarea is focused. Built by
| MobileKeyboardHelper; appended to document.body and positioned with `bottom`
| set to the live keyboard inset.
|-----------------------------------------------------------------------------*/

.theia-mobile-keyboard-accessory {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9700;
  display: none;
  flex-direction: row;
  align-items: stretch;
  min-height: 40px;
  padding: 4px 6px;
  gap: 4px;
  background: var(--theia-editorWidget-background, var(--theia-statusBar-background));
  color: var(--theia-editorWidget-foreground, var(--theia-statusBar-foreground));
  border-top: 1px solid var(--theia-editorWidget-border, var(--theia-statusBar-border, transparent));
  box-sizing: border-box;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x;
  /* iOS treats taps inside a fixed bar that the keyboard "owns" as scroll attempts;
     opting out keeps key buttons immediately tappable. */
  -webkit-user-select: none;
  user-select: none;
}

.theia-mobile-keyboard-accessory.theia-mod-visible {
  display: flex;
}

.theia-mobile-keyboard-accessory::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

.theia-mobile-keyboard-accessory-btn {
  flex: 0 0 auto;
  min-width: 40px;
  min-height: 36px;
  padding: 0 12px;
  margin: 0;
  border: none;
  border-radius: 6px;
  background: var(--theia-button-secondaryBackground, rgba(255, 255, 255, 0.08));
  color: inherit;
  font-family: var(--theia-monospace-font-family, monospace);
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 100ms ease;
}

.theia-mobile-keyboard-accessory-btn:active {
  background: var(--theia-button-secondaryHoverBackground, rgba(255, 255, 255, 0.16));
}

/*-----------------------------------------------------------------------------
| iOS Safari triggers a viewport zoom whenever a focused input has a font size
| smaller than 16px. The mobile breakpoint above sets `.theia-input` to 15px
| (matching --theia-ui-font-size1) which is otherwise good for density. Bump
| inputs to 16px on iOS only via `-webkit-touch-callout` (a property only
| implemented in iOS WebKit) so other platforms keep the tighter sizing.
|-----------------------------------------------------------------------------*/

@media (max-width: 767px),
(pointer: coarse) {
  @supports (-webkit-touch-callout: none) {

    .theia-input,
    input.theia-input,
    select.theia-input,
    textarea.theia-input,
    #quick-input-container .monaco-inputbox>.ibwrapper>.input,
    .theia-mobile-projects-search-input,
    .theia-mobile-open-repo-filter-input,
    .theia-mobile-open-repo-public-input,
    .lm-Widget.dialogOverlay input,
    .lm-Widget.dialogOverlay textarea,
    .lm-Widget.dialogOverlay select,
    /* Monaco editor find/replace widget (Ctrl+F): inputs sit above the editor and
       would otherwise trigger the iOS zoom-on-focus loop, dropping focus and
       making the widget unusable on phones. */
    .monaco-editor .find-widget .monaco-inputbox>.ibwrapper>.input,
    .monaco-editor .find-widget .monaco-inputbox>.ibwrapper>textarea,
    .monaco-editor .find-widget input,
    /* SCM commit message textarea. */
    .theia-scm-input-message-container textarea,
    /* Transcript Files tab Monaco editor. */
    .theia-mobile-transcript-files-monaco-host .monaco-editor textarea.inputarea,
    /* Search across files / replace inputs. */
    .t-siw-search-container input,
    .t-siw-search-container textarea,
    /* Notebook find/replace widget. */
    .theia-notebook-find-widget input,
    /* Terminal in-pane search (Ctrl+F in terminal). */
    .terminal-search-container input,
    /* Any Monaco-styled inputbox that surfaces above content (peek widgets,
       rename, parameter hints input) — same zoom-on-focus failure mode. */
    .monaco-inputbox>.ibwrapper>.input,
    .monaco-inputbox>.ibwrapper>textarea,
    /* Monaco rename popup input (F2 on a symbol). */
    .monaco-editor .rename-box input {
      font-size: 16px;
    }
  }
}

/* Quick Input dimmed backdrop — tap outside to dismiss (mobile). */
.theia-mobile-quick-input-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 2147482999;
  background: rgba(0, 0, 0, 0.35);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-quick-input-backdrop.theia-mod-visible {
  opacity: 1;
  pointer-events: auto;
}

@media (max-width: 767px),
(pointer: coarse) {
  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container {
    top: auto !important;
    right: 0 !important;
    bottom: calc(var(--theia-mobile-status-chrome-height, 34px) + 6px) !important;
    left: 0 !important;
    width: 100vw !important;
    max-width: 100vw !important;
    padding: 0 max(10px, env(safe-area-inset-right, 0px)) 0 max(10px, env(safe-area-inset-left, 0px)) !important;
    box-sizing: border-box;
    display: flex;
    align-items: flex-end;
    pointer-events: none;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-widget {
    position: relative !important;
    top: auto !important;
    right: auto !important;
    bottom: auto !important;
    left: auto !important;
    width: 100% !important;
    max-width: 100% !important;
    max-height: min(72dvh, 560px) !important;
    margin: 0 !important;
    border: 1px solid color-mix(in srgb, var(--theia-foreground) 14%, transparent) !important;
    border-radius: 14px !important;
    background: var(--theia-quickInput-background, var(--theia-editor-background)) !important;
    box-shadow: 0 18px 48px rgba(0, 0, 0, 0.42) !important;
    overflow: hidden;
    pointer-events: auto;
    transform: none !important;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-titlebar {
    min-height: 34px;
    padding: 8px 12px 2px;
    background: var(--theia-quickInput-background, var(--theia-editor-background)) !important;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-box,
  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-and-message {
    padding: 8px 12px 10px;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .monaco-inputbox>.ibwrapper>.input {
    min-height: 44px !important;
    font-size: 16px !important;
    border-radius: 10px !important;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list {
    max-height: calc(min(72dvh, 560px) - 104px) !important;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list .monaco-list-row {
    min-height: 52px !important;
    height: 52px !important;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list .quick-input-list-row {
    padding: 12px 12px;
    box-sizing: border-box;
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list .monaco-list-row:not(:last-child) {
    border-bottom: 1px solid color-mix(in srgb, var(--theia-foreground) 8%, transparent);
  }

  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list .label-name,
  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list .label-description,
  body.theia-mobile-mod-project-switcher-quickpick #quick-input-container .quick-input-list .label-detail {
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

/*-----------------------------------------------------------------------------
| Mobile projects workspace view (full-screen overlay above main area).
|-----------------------------------------------------------------------------*/

#theia-app-shell.theia-mod-mobile-one-column .theia-mobile-projects {
  position: fixed;
  top: env(safe-area-inset-top, 0px);
  left: 0;
  right: 0;
  /* Sticky composer + workspace bar sit on this edge; include keyboard inset (iOS Safari overlay keyboard). */
  bottom: var(--theia-mobile-bottom-chrome-stack);
  z-index: 9550;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  background: var(--theia-editor-background);
  color: var(--theia-foreground);
  box-sizing: border-box;
  transform: translateY(8px);
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

#theia-app-shell.theia-mod-mobile-one-column .theia-mobile-projects.theia-mod-visible {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}

/*
