}

.theia-mobile-projects-header {
  position: sticky;
  top: 0;
  z-index: 7;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 14px 16px 8px;
  background: var(--theia-editor-background);
  box-shadow: 0 -4px 0 4px var(--theia-editor-background);
}

.theia-mobile-projects-header-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-width: 0;
}

.theia-mobile-projects-search-toggle.theia-mod-active {
  color: var(--theia-foreground);
  background: color-mix(in srgb, var(--theia-foreground) 10%, transparent);
}

.theia-mobile-projects-search-toggle[hidden],
.theia-mobile-projects-new-chat-btn[hidden] {
  display: none !important;
}

.theia-mobile-projects-new-chat-btn .codicon {
  font-size: 18px;
}

.theia-mobile-projects-title {
  margin: 0;
