  font-weight: 600;
  line-height: 1;
  cursor: pointer;
}

.theia-mobile-work-hub-home-usage-pill.theia-mod-selected {
  background: var(--q-surface, var(--theia-editor-background));
  color: var(--qaap-ink, var(--q-text, var(--theia-foreground)));
