}

.theia-mobile-work-hub-home-usage-heatmap-cell.theia-mod-level-1 {
  background: color-mix(in srgb, var(--q-accent, var(--theia-button-background)) 28%, transparent);
}

.theia-mobile-work-hub-home-usage-heatmap-cell.theia-mod-level-2 {
  background: color-mix(in srgb, var(--q-accent, var(--theia-button-background)) 48%, transparent);
