.theia-mobile-work-hub-home-usage-heatmap-cell.theia-mod-level-3 {
  background: color-mix(in srgb, var(--q-accent, var(--theia-button-background)) 68%, transparent);
}

.theia-mobile-work-hub-home-usage-heatmap-cell.theia-mod-level-4 {
  background: color-mix(in srgb, var(--q-accent, var(--theia-button-background)) 88%, transparent);
}

.theia-mobile-work-hub-home-usage-footnote {
