  color: var(--qaap-muted, var(--q-muted, var(--theia-descriptionForeground)));
}

.theia-mobile-work-hub-home-usage-models {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.theia-mobile-work-hub-home-usage-model-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
