}

.theia-mobile-work-hub-home-shortcut-body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
}

.theia-mobile-work-hub-home-shortcut-title {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--qaap-ink, var(--q-text, var(--theia-foreground)));
}

.theia-mobile-work-hub-home-shortcut-hint {
  font-size: 11px;
  font-weight: 400;
  line-height: 1.25;
  color: var(--qaap-muted, var(--q-muted, var(--theia-descriptionForeground)));
  /* Wrap to a second line instead of clipping mid-word; the cell reserves height for two lines. */
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
}

.theia-mobile-work-hub-home-section-panel {
  padding: 12px 12px 6px;
}

.theia-mobile-work-hub-home-section-panel.theia-mod-attention {
  border-color: color-mix(in srgb, var(--q-danger, var(--theia-errorForeground)) 28%, var(--q-line, transparent));
}

.theia-mobile-work-hub-home-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.theia-mobile-work-hub-home-section-action {
  flex: 0 0 auto;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--q-accent-ink, var(--q-accent, var(--theia-button-background)));
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: -0.01em;
  cursor: pointer;
}

.theia-mobile-work-hub-home-section-action:active {
  opacity: 0.7;
}

.theia-mobile-work-hub-home-rows {
  display: flex;
