}

.theia-mobile-work-hub-home-row.theia-mod-attention {
  padding-left: 10px;
}

.theia-mobile-work-hub-home-row-marker,
.theia-mobile-work-hub-home-row-leading,
.theia-mobile-work-hub-home-row-avatar,
.theia-mobile-work-hub-home-row-chevron {
