  align-items: center;
  justify-content: center;
  border-radius: var(--q-radius-icon, 10px);
  background: color-mix(in srgb, var(--qaap-ink, var(--q-text, var(--theia-foreground))) 6%, transparent);
  font-size: 16px;
  line-height: 1;
  color: var(--qaap-muted, var(--q-muted, var(--theia-descriptionForeground)));
}

.theia-mobile-work-hub-home-row-avatar {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--q-radius-icon, 10px);
  border: 1px solid color-mix(in srgb, var(--qaap-mobile-project-accent, var(--q-line)) 24%, transparent);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.03em;
  color: var(--qaap-mobile-project-accent, var(--qaap-ink-2, var(--q-text-2, var(--theia-foreground))));
  background: color-mix(in srgb, var(--qaap-mobile-project-accent, var(--q-line)) 10%, transparent);
}

.theia-mobile-work-hub-home-row-body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  align-self: center;
}

.theia-mobile-work-hub-home-row-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.theia-mobile-work-hub-home-row-dot {
  flex: 0 0 auto;
}

.theia-mobile-work-hub-home-row-title {
  min-width: 0;
  font-size: 14px;
  font-weight: 550;
  line-height: 1.25;
  letter-spacing: -0.02em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--qaap-ink, var(--q-text, var(--theia-foreground)));
