}

.theia-mobile-projects.theia-mod-home.theia-mod-hub-home .theia-mobile-projects-title {
  font-size: clamp(22px, 5.5vw, 26px);
  font-weight: 600;
  letter-spacing: -0.04em;
  line-height: 1.1;
  color: var(--qaap-ink, var(--q-text, var(--theia-foreground)));
}

.theia-mobile-projects.theia-mod-home.theia-mod-hub-home .theia-mobile-projects-subtitle {
  display: block;
  margin-top: 5px;
  max-width: none;
  color: var(--qaap-muted, var(--q-muted, var(--theia-descriptionForeground)));
}

/* Work Hub Team tab — leaders and qaap-task subtasks. */
.theia-mobile-hub-team-root {
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.theia-mobile-hub-team {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 4px 12px 16px;
  flex: 1 1 auto;
}

.theia-mobile-hub-team-row {
  display: flex;
  gap: 12px;
  align-items: stretch;
  width: 100%;
  padding: 14px 12px;
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.18));
  border-radius: 14px;
  background: color-mix(in srgb, var(--theia-editor-background) 94%, var(--theia-foreground) 6%);
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.theia-mobile-hub-team-row.theia-mod-nested {
  margin-left: 18px;
  width: calc(100% - 18px);
  padding: 10px 12px;
  border-style: dashed;
  opacity: 0.92;
}

.theia-mobile-hub-team-icon {
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  background: color-mix(in srgb, var(--q-accent, #E58E40) 22%, transparent);
}

.theia-mobile-hub-team-icon.theia-mod-running {
  background: color-mix(in srgb, var(--theia-charts-green, #4caf7c) 24%, transparent);
}

.theia-mobile-hub-team-icon.theia-mod-failed {
  background: color-mix(in srgb, var(--theia-errorForeground, #f14c4c) 18%, transparent);
}

.theia-mobile-hub-team-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.theia-mobile-hub-team-title-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.theia-mobile-hub-team-title {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.theia-mobile-hub-team-since {
