  align-items: center;
  gap: 6px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-hub-team-prog {
  height: 3px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--theia-foreground) 10%, transparent);
  overflow: hidden;
  margin-top: 4px;
}

.theia-mobile-hub-team-prog>i {
