  font-size: 11px;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-hub-team-workflows-link {
  display: block;
  width: calc(100% - 24px);
  margin: 8px 12px 24px;
  padding: 12px;
  border: none;
  border-radius: 12px;
  background: color-mix(in srgb, var(--theia-foreground) 6%, transparent);
  color: var(--theia-descriptionForeground);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  text-align: center;
}

.theia-mobile-projects-empty.theia-mod-team-empty {
  padding: 32px 24px 16px;
}

.theia-mobile-hub-team-row:active {
