}

.theia-mobile-hub-team-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 4px 10px;
}

.theia-mobile-hub-team-section-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-hub-team-section-count {
  font-family: var(--monaco-monospace-font, monospace);
  font-size: 11px;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-hub-team-icon.theia-mod-running {
