/* Sticky global composer (Work Hub project detail + Agents landing). */
.theia-mobile-projects {
  --qaap-composer-edge-inset: 12px;
}

@media (min-width: 768px) {
  .theia-mobile-projects {
    --qaap-composer-edge-inset: 14px;
  }
}

.theia-mobile-projects.theia-mod-agents-hub-inline-active,
.theia-mobile-projects.theia-mod-agents-hub-shell-active {
  --qaap-composer-edge-inset: max(var(--theia-mobile-execution-chrome-pad-x, 12px), 12px);
}

.theia-mobile-projects.theia-mod-sticky-composer {
  display: flex;
  flex-direction: column;
}

.theia-mobile-projects.theia-mod-sticky-composer .theia-mobile-projects-scroll {
  flex: 1 1 auto;
  min-height: 0;
}

/*
 * Transcript scrollport vs composer lip — negative value overlaps the composer
 * top edge. Composer clearance stays geometric
 * (flex sibling below the scroll host). `--theia-mobile-projects-fab-lift` is
 * only for FAB lift.
 */
.theia-mobile-projects {
  --theia-mobile-transcript-composer-scroll-gap: -28px;
}

.theia-mobile-projects.theia-mod-sticky-composer>.theia-mobile-projects-sticky-composer:not([hidden]),
.theia-mobile-agent-transcript-root .theia-mobile-agent-transcript-chat-input {
  margin-top: var(--theia-mobile-transcript-composer-scroll-gap, -28px);
}

.theia-mobile-projects-sticky-composer {
  flex-shrink: 0;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  padding: 8px max(var(--qaap-composer-edge-inset, 12px), env(safe-area-inset-right, 0px)) calc(10px + env(safe-area-inset-bottom, 0px));
  padding-left: max(var(--qaap-composer-edge-inset, 12px), env(safe-area-inset-left, 0px));
  padding-right: max(var(--qaap-composer-edge-inset, 12px), env(safe-area-inset-right, 0px));
  background: color-mix(in srgb, var(--theia-editor-background) 88%, transparent);
  backdrop-filter: blur(12px);
