.theia-mobile-sticky-composer-activity-head-actions {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.theia-mobile-sticky-composer-activity-bulk-action {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 90%, var(--theia-foreground));
  font: inherit;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.theia-mobile-sticky-composer-activity-bulk-action:hover:not(:disabled),
.theia-mobile-sticky-composer-activity-bulk-action:focus-visible:not(:disabled) {
  color: var(--theia-foreground);
}

.theia-mobile-sticky-composer-activity-bulk-action:disabled {
  opacity: 0.45;
  cursor: default;
}

.theia-mobile-sticky-composer-activity-review {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 4px 11px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 10%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--theia-foreground) 6%, transparent);
  color: var(--theia-foreground);
  font: inherit;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.theia-mobile-sticky-composer-activity-review:hover,
.theia-mobile-sticky-composer-activity-review:focus-visible {
  background: color-mix(in srgb, var(--theia-foreground) 10%, transparent);
}

.theia-mobile-sticky-composer-activity-body {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  max-height: min(24vh, 180px);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  overscroll-behavior-y: contain;
  padding: 0 12px 6px;
}

.theia-mobile-sticky-composer-activity-body[hidden] {
  display: none !important;
}

.theia-mobile-sticky-composer-activity-section.theia-mod-queue .theia-mobile-sticky-composer-activity-body {
  padding-top: 2px;
}

.theia-mobile-sticky-composer-queue-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  padding: 5px 2px;
}

.theia-mobile-sticky-composer-queue-marker {
  flex: 0 0 7px;
  width: 7px;
  height: 7px;
  margin-top: 5px;
  border: 1.5px solid color-mix(in srgb, var(--theia-descriptionForeground) 55%, transparent);
  border-radius: 999px;
}

.theia-mobile-sticky-composer-queue-text {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 12px;
  line-height: 1.35;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 92%, var(--theia-foreground));
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.theia-mobile-sticky-composer-queue-actions {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 0;
  opacity: 0.72;
}

.theia-mobile-sticky-composer-queue-item:hover .theia-mobile-sticky-composer-queue-actions,
.theia-mobile-sticky-composer-queue-item:focus-within .theia-mobile-sticky-composer-queue-actions {
  opacity: 1;
}

.theia-mobile-sticky-composer-queue-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--theia-descriptionForeground);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.theia-mobile-sticky-composer-queue-action .codicon {
  font-size: 13px;
}

.theia-mobile-sticky-composer-queue-action:hover,
.theia-mobile-sticky-composer-queue-action:focus-visible {
  background: color-mix(in srgb, var(--theia-foreground) 7%, transparent);
  color: var(--theia-foreground);
}

.theia-mobile-sticky-composer-file-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 26px;
  padding: 3px 2px;
}

.theia-mobile-sticky-composer-file-icon {
  flex: 0 0 auto;
  font-size: 13px;
  opacity: 0.78;
}

.theia-mobile-sticky-composer-file-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  color: color-mix(in srgb, var(--theia-foreground) 90%, var(--theia-descriptionForeground));
}

.theia-mobile-sticky-composer-file-stats {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.theia-mobile-sticky-composer-file-stats .theia-mobile-agent-diff-stat {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  font-family: var(--theia-code-font-family, ui-monospace, monospace);
  font-size: 9px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.theia-mobile-sticky-composer-file-stats .theia-mobile-agent-diff-stat.theia-mod-added {
  color: color-mix(in srgb, var(--theia-charts-green, #3fb950) 88%, var(--theia-descriptionForeground));
}

.theia-mobile-sticky-composer-file-stats .theia-mobile-agent-diff-stat.theia-mod-removed {
  color: color-mix(in srgb, var(--theia-errorForeground, #f85149) 88%, var(--theia-descriptionForeground));
}

.theia-mobile-sticky-composer-files-more {
  padding: 2px 2px 0;
  font-size: 11px;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-sticky-composer-mode-banner,
.theia-mobile-sticky-composer-legacy-banner {
  margin: 0 0 8px;
  padding: 8px 12px;
  border-radius: 10px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--theia-descriptionForeground);
  background: color-mix(in srgb, var(--q-accent, #E58E40) 10%, var(--theia-editorWidget-background));
  border: 1px solid color-mix(in srgb, var(--q-accent, #E58E40) 22%, transparent);
}

.theia-mobile-sticky-composer-legacy-banner {
  background: color-mix(in srgb, var(--theia-descriptionForeground) 8%, var(--theia-editorWidget-background));
  border-color: color-mix(in srgb, var(--theia-panel-border) 70%, transparent);
}

/* Tool UI approval-card pattern (ported from tool-ui.com). */
.theia-mobile-agent-approval-card {
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border, color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 70%, transparent));
  background: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  box-shadow: 0 1px 2px color-mix(in srgb, var(--theia-widget-shadow, #000) 14%, transparent);
}

.theia-mobile-agent-approval-card.theia-mod-inline {
  margin: 8px 0 0;
}

.theia-mobile-agent-approval-card-head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 12px 10px;
}

.theia-mobile-agent-approval-card-icon {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  font-size: 15px;
  color: var(--q-accent, #E58E40);
  background: color-mix(in srgb, var(--q-accent, #E58E40) 14%, transparent);
}

.theia-mobile-agent-approval-card-copy {
  flex: 1 1 auto;
  min-width: 0;
}

.theia-mobile-agent-approval-card-title {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--theia-foreground);
}

.theia-mobile-agent-approval-card-description {
  margin: 5px 0 0;
  font-size: 12px;
  line-height: 1.45;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-approval-card-sep {
  height: 1px;
  background: color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 78%, transparent);
}

.theia-mobile-agent-approval-card-actions {
  display: flex;
  gap: 8px;
  padding: 10px 12px 12px;
}

.theia-mobile-agent-approval-card-deny,
.theia-mobile-agent-approval-card-allow {
  flex: 1 1 0;
  min-height: 40px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-approval-card-deny {
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.28)) 80%, transparent);
  background: transparent;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-approval-card-deny:active {
  background: color-mix(in srgb, var(--theia-foreground, #fff) 6%, transparent);
}

.theia-mobile-agent-approval-card-allow {
  border: 1px solid color-mix(in srgb, var(--q-accent, #E58E40) 42%, transparent);
  background: color-mix(in srgb, var(--q-accent, #E58E40) 20%, transparent);
  color: var(--theia-foreground);
}

.theia-mobile-agent-approval-card-allow:active {
  background: color-mix(in srgb, var(--q-accent, #E58E40) 30%, transparent);
}

/* Tool UI rich content cards in transcript markdown + tool payloads. */
.theia-mobile-agent-rich-card-sep {
  height: 1px;
  background: color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 78%, transparent);
}

.theia-mobile-agent-rich-copy {
  position: relative;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  margin-left: auto;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--theia-descriptionForeground);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-rich-copy:active,
.theia-mobile-agent-rich-copy:focus-visible {
  color: var(--theia-foreground);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 8%, transparent);
}

.theia-mobile-agent-rich-copy-tip {
  position: absolute;
  top: calc(100% + 5px);
  right: 0;
  z-index: 2;
  padding: 4px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  color: var(--theia-editorWidget-foreground, var(--theia-foreground));
  background: var(--theia-editorWidget-background, var(--theia-sideBar-background));
  border: 1px solid var(--theia-editorWidget-border, var(--theia-panel-border, transparent));
  opacity: 0;
  pointer-events: none;
}

.theia-mobile-agent-rich-copy.theia-mod-copied .theia-mobile-agent-rich-copy-tip {
  opacity: 1;
}

.theia-mobile-agent-code-block-card,
.theia-mobile-agent-link-preview-card,
.theia-mobile-agent-citation-card,
.theia-mobile-agent-option-list-card,
.theia-mobile-agent-question-flow-card {
  overflow: hidden;
  margin: 8px 0 12px;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border, color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 70%, transparent));
  background: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  box-shadow: 0 1px 2px color-mix(in srgb, var(--theia-widget-shadow, #000) 14%, transparent);
  text-decoration: none;
  color: inherit;
}

.theia-mobile-agent-code-block-card-head,
.theia-mobile-agent-option-list-card-head,
.theia-mobile-agent-question-flow-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 11px;
  font-size: 12px;
  font-weight: 600;
  color: var(--theia-foreground);
}

.theia-mobile-agent-code-block-card-language {
  font-family: var(--theia-code-font-family, monospace);
  font-size: 11px;
  font-weight: 500;
  color: var(--theia-descriptionForeground);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.theia-mobile-agent-code-block-card-body {
  padding: 0 0 4px;
  overflow-x: auto;
}

.theia-mobile-agent-code-block-card-body .theia-mobile-agent-code-view {
  border: none;
  border-radius: 0;
  background: transparent;
}

.theia-mobile-agent-link-preview-card {
  display: block;
}

.theia-mobile-agent-link-preview-card-head {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.theia-mobile-agent-link-preview-card-image {
  display: block;
  width: 100%;
  max-height: 160px;
  object-fit: cover;
  border-bottom: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 70%, transparent);
}

.theia-mobile-agent-link-preview-card-copy {
  padding: 10px 12px 12px;
}

.theia-mobile-agent-link-preview-card-domain,
.theia-mobile-agent-citation-card-domain {
  font-size: 11px;
  font-weight: 500;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-link-preview-card-title,
.theia-mobile-agent-citation-card-title {
  margin-top: 3px;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  color: var(--theia-foreground);
}

.theia-mobile-agent-link-preview-card-description,
.theia-mobile-agent-citation-card-snippet {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.45;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-citation-card-head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px 12px;
}

.theia-mobile-agent-citation-card-icon {
  flex: none;
  font-size: 15px;
  color: var(--theia-textLink-foreground, var(--theia-focusBorder, #4c9aff));
}

.theia-mobile-agent-option-list-card-options,
.theia-mobile-agent-question-flow-card-options {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 11px 11px;
}

.theia-mobile-agent-option-list-card-option,
.theia-mobile-agent-question-flow-card-option {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.22)) 75%, transparent);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 4%, transparent);
}

.theia-mobile-agent-option-list-card-option.theia-mod-selected,
.theia-mobile-agent-question-flow-card-option.theia-mod-selected {
  border-color: color-mix(in srgb, var(--q-accent, #E58E40) 42%, transparent);
  background: color-mix(in srgb, var(--q-accent, #E58E40) 12%, transparent);
}

.theia-mobile-agent-option-list-card-marker,
.theia-mobile-agent-question-flow-card-marker {
  flex: none;
  width: 14px;
  font-size: 12px;
  line-height: 1.35;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-option-list-card-label,
.theia-mobile-agent-question-flow-card-option-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--theia-foreground);
}

.theia-mobile-agent-option-list-card-description {
  margin-top: 3px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-question-flow-card-steps {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 11px 11px;
}

.theia-mobile-agent-question-flow-card-step {
  padding: 10px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 70%, transparent);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 3%, transparent);
}

.theia-mobile-agent-question-flow-card-step-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.theia-mobile-agent-question-flow-card-step-index {
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--theia-foreground);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 10%, transparent);
}

.theia-mobile-agent-question-flow-card-step-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--theia-foreground);
}

.theia-mobile-agent-question-flow-card-question {
  margin: 0 0 8px;
  font-size: 12px;
  line-height: 1.45;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-sticky-composer-pending-approval-host {
  width: 100%;
  min-width: 0;
  flex-shrink: 0;
  box-sizing: border-box;
  padding: 0 4px 8px;
  pointer-events: auto;
  position: relative;
  z-index: 12;
}

.theia-mobile-sticky-composer-pending-approval-host .theia-mobile-agent-approval-card.theia-mod-inline {
  margin: 0;
  box-shadow: 0 8px 24px color-mix(in srgb, var(--theia-widget-shadow, #000) 42%, transparent);
  animation: qaap-transcript-approval-pulse 1.8s ease-in-out infinite;
}

@keyframes qaap-transcript-approval-pulse {

  0%,
  100% {
    border-color: color-mix(in srgb, var(--q-accent, #E58E40) 34%, var(--theia-widget-border, rgba(128, 128, 128, 0.24)));
  }

  50% {
    border-color: color-mix(in srgb, var(--q-accent, #E58E40) 62%, var(--theia-widget-border, rgba(128, 128, 128, 0.24)));
  }
}

.theia-mobile-agent-tool-pill.theia-mod-awaiting-approval>summary .theia-mobile-agent-tool-pill-verb::after {
  content: ' · waiting';
  font-weight: 500;
  color: var(--q-accent, #E58E40);
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-approval-card.theia-mod-pill {
  margin-bottom: 8px;
  pointer-events: auto;
  touch-action: manipulation;
}

.theia-mobile-agent-transcript-inline-preview {
  margin: 8px 0 0;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, #3fb950 35%, transparent);
  background: color-mix(in srgb, #3fb950 10%, var(--theia-editor-background));
}

.theia-mobile-agent-transcript-inline-preview-title {
  font-size: 13px;
  font-weight: 600;
}

.theia-mobile-agent-transcript-inline-preview-summary {
  margin: 6px 0 10px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-transcript-inline-preview-actions {
  display: flex;
  gap: 8px;
}

.theia-mobile-agent-transcript-inline-preview-open {
  flex: 1;
  min-height: 40px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, #3fb950 45%, transparent);
  background: color-mix(in srgb, #3fb950 16%, transparent);
  color: var(--theia-foreground);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.theia-mobile-projects-sticky-composer-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  background: color-mix(in srgb, var(--theia-editor-background) 94%, var(--theia-foreground) 6%);
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--theia-foreground) 8%, transparent),
    0 10px 28px color-mix(in srgb, #000 14%, transparent);
  overflow: hidden;
  box-sizing: border-box;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.theia-mobile-projects-sticky-composer-context-strip {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 10px 8px;
  border-bottom: 1px solid color-mix(in srgb, var(--theia-foreground) 8%, transparent);
  background: color-mix(in srgb, var(--theia-foreground) 3%, transparent);
  animation: qaap-sticky-context-strip-in 180ms ease-out;
}

.theia-mobile-projects-sticky-composer-context-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}

.theia-mobile-projects-sticky-composer-context-head-main {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.theia-mobile-projects-sticky-composer-context-files-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: none;
  background: transparent;
  color: inherit;
  margin: 0;
  padding: 0;
  cursor: pointer;
  border-radius: 6px;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-projects-sticky-composer-context-files-toggle:hover,
.theia-mobile-projects-sticky-composer-context-files-toggle:focus-visible {
  color: var(--theia-foreground);
  outline: none;
}

.theia-mobile-projects-sticky-composer-context-files-toggle .codicon {
  font-size: 12px;
  opacity: 0.8;
  transition: transform 120ms ease;
}

.theia-mobile-projects-sticky-composer-context-files-toggle.theia-mod-collapsed .codicon {
  transform: rotate(-90deg);
}

.theia-mobile-projects-sticky-composer-context-head-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-projects-sticky-composer-context-count {
  display: inline-flex;
