.theia-mobile-projects-row-head {
  position: sticky;
  top: 0;
  z-index: 4;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 4px;
  background: var(--qaap-bg, var(--theia-editor-background, var(--q-bg)));
  border: none;
  border-bottom: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.16));
  cursor: pointer;
  color: var(--theia-foreground);
  font-family: inherit;
  text-align: left;
  transition: var(--qaap-mobile-state-transition);
}

.theia-mobile-projects-row-head:hover,
.theia-mobile-projects-row-head:focus-visible {
  background: var(--qaap-mobile-hover-bg);
  outline: none;
}

.theia-mobile-projects-row-head:active {
  background: var(--qaap-mobile-active-bg);
}

.theia-mobile-projects-row-glyph {
  position: relative;
  flex: 0 0 12px;
  width: 12px;
  height: 12px;
}

.theia-mobile-projects-row-glyph::before {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: 999px;
  background: var(--theia-panel-border, rgba(128, 128, 128, 0.4));
}

.theia-mobile-projects-row-glyph.theia-mod-workspace::before {
  inset: 0;
  background: transparent;
  border: 2px solid var(--q-accent, var(--qaap-accent, #E58E40));
}

.theia-mobile-projects-row-glyph.theia-mod-running::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: var(--theia-charts-green, #4caf7c);
  animation: theia-mobile-projects-pulse 1.2s ease-in-out infinite;
}

.theia-mobile-projects-row-glyph.theia-mod-workspace.theia-mod-running::after {
  inset: 3px;
}

.theia-mobile-projects-row-glyph.theia-mod-done::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 999px;
  background: var(--theia-charts-green, #4caf7c);
  opacity: 0.55;
}

.theia-mobile-projects-row-glyph.theia-mod-workspace.theia-mod-done::after {
  inset: 4px;
}

/* Needs your input — amber pulsing dot. */
.theia-mobile-projects-row-glyph.theia-mod-needs-input::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: var(--theia-notificationsWarningIcon-foreground, #cca700);
  animation: theia-mobile-projects-pulse 1.2s ease-in-out infinite;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theia-notificationsWarningIcon-foreground, #cca700) 22%, transparent);
}

.theia-mobile-projects-row-glyph.theia-mod-workspace.theia-mod-needs-input::after {
  inset: 3px;
}

/* Last turn failed — red dot, static so the user notices but isn't visually nagged. */
.theia-mobile-projects-row-glyph.theia-mod-failed::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: var(--theia-errorForeground, #f14c4c);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theia-errorForeground, #f14c4c) 22%, transparent);
}

.theia-mobile-projects-row-glyph.theia-mod-workspace.theia-mod-failed::after {
  inset: 3px;
}

/* Unread agent reply — blue dot with a soft halo. Doesn't pulse so it stays distinguishable
   from the running state at the project list level. */
.theia-mobile-projects-row-glyph.theia-mod-unread::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: var(--theia-charts-blue, #4c9aff);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theia-charts-blue, #4c9aff) 22%, transparent);
}

.theia-mobile-projects-row-glyph.theia-mod-workspace.theia-mod-unread::after {
  inset: 3px;
}

.theia-mobile-projects-row-main {
  flex: 1 1 auto;
  min-width: 0;
}

.theia-mobile-projects-row-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.theia-mobile-projects-row-name-group {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 1 1 auto;
  min-width: 0;
}

.theia-mobile-projects-row-name-group .theia-mobile-projects-row-name {
