/* Inline composer — collapsed (single row) and expanded (full chrome) variants */
@keyframes theia-mobile-projects-composer-expand {
  0% {
    opacity: 0;
    transform: translateY(-4px) scaleY(0.92);
  }

  100% {
    opacity: 1;
    transform: translateY(0) scaleY(1);
  }
}

@keyframes theia-mobile-projects-fade-in {
  from {
    opacity: 0;
    transform: translateY(2px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes theia-mobile-projects-expand-content {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes theia-mobile-projects-flash-in {
  0% {
    background: color-mix(in srgb, var(--q-accent, var(--qaap-accent, #E58E40)) 22%, transparent);
  }

  100% {
    background: transparent;
  }
}

