  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent !important;
  box-shadow: none;
}

/* "Done" badge: a bare green ring-check glyph (codicon-pass) with no filled
   bubble behind it. */
.theia-mobile-projects-task-dot.theia-mod-complete {
  background: transparent !important;
  color: var(--theia-charts-green, #4caf7c);
}

.theia-mobile-projects-task-dot.theia-mod-verified {
  background: transparent !important;
  color: var(--theia-charts-green, #4caf7c);
}

.theia-mobile-projects-task-dot.theia-mod-pr-ready {
