.theia-mobile-projects-task-dot.theia-mod-checks-pending,
.theia-mobile-projects-task-dot.theia-mod-changes {
  color: var(--theia-notificationsWarningIcon-foreground, #bf8700);
}

.theia-mobile-projects-task-dot.theia-mod-pr-draft,
.theia-mobile-projects-task-dot.theia-mod-pr-unknown {
  color: var(--theia-descriptionForeground);
}

/* Bare ring glyphs to match the "Done" badge: no filled bubble, colored icon. */
.theia-mobile-projects-task-dot.theia-mod-failed {
  background: transparent !important;
  color: var(--theia-errorForeground, #f14c4c);
}

.theia-mobile-projects-task-dot.theia-mod-needs-input {
  background: transparent !important;
  color: var(--theia-notificationsWarningIcon-foreground, #cca700);
}

/*
 * "Needs you" warning glyph — slow attention pulse (the "baje en mute" throb).
 * The glyph itself breathes so the user's eye is drawn to the task that needs
 * them, without the aggressive blink of a notification badge.
 */
.theia-mobile-projects-task-dot.theia-mod-needs-input .theia-mobile-projects-task-leading-glyph.codicon-warning {
  animation: qaap-needs-you-throb 1.8s ease-in-out infinite;
}

@keyframes qaap-needs-you-throb {

  0%,
  100% {
    opacity: 1;
    transform: scale(1);
    filter: drop-shadow(0 0 0 transparent);
  }

  50% {
    opacity: 0.65;
    transform: scale(1.18);
    filter: drop-shadow(0 0 6px color-mix(in srgb, var(--theia-notificationsWarningIcon-foreground, #cca700) 55%, transparent));
  }
}

@media (prefers-reduced-motion: reduce) {
  .theia-mobile-projects-task-dot.theia-mod-needs-input .theia-mobile-projects-task-leading-glyph.codicon-warning {
    animation: none;
  }
}

