  background: color-mix(in srgb, var(--theia-testing-iconFailed, #c72e0f) 12%, var(--theia-editorWidget-background, var(--theia-editor-background)));
}

.theia-mobile-pr-toast>span {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
}

.theia-mobile-pr-toast button {
  flex: 0 0 auto;
  min-height: 28px;
  padding: 4px 8px;
  border: none;
  border-radius: 7px;
  background: var(--theia-toolbar-hoverBackground);
  color: var(--theia-foreground);
  font-size: 12px;
  font-weight: 700;
}

.theia-mobile-pr-confetti {
  position: absolute;
  inset: 0;
  z-index: 3;
  overflow: hidden;
  pointer-events: none;
}

.theia-mobile-pr-confetti span {
  position: absolute;
  left: 50%;
  top: 46%;
  width: 7px;
  height: 11px;
  border-radius: 2px;
  background: var(--color);
  transform: translate(-50%, -50%);
  animation: qaap-mobile-pr-confetti 1200ms cubic-bezier(0.18, 0.78, 0.18, 1) forwards;
  animation-delay: var(--delay);
}

.theia-mobile-pr-confetti span:nth-child(3n) {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.theia-mobile-pr-confetti span:nth-child(4n) {
  width: 10px;
  height: 4px;
}

@keyframes qaap-mobile-pr-pulse {

  0%,
  100% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.06);
  }
}

@keyframes qaap-mobile-pr-confetti {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.7) rotate(0deg);
  }

  12% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--x)), 230px) scale(1) rotate(var(--rot));
  }
}

/*-----------------------------------------------------------------------------
