/*-----------------------------------------------------------------------------
| Desktop status bar: horizontal scroll when entries overflow (thin scrollbar).
|-----------------------------------------------------------------------------*/

@media (min-width: 768px) {
  #theia-statusBar {
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--theia-scrollbarSlider-background, rgba(128, 128, 128, 0.45)) transparent;
  }

  #theia-statusBar .theia-statusBar-track {
    width: max-content;
    min-width: 100%;
    flex-wrap: nowrap;
  }

  #theia-statusBar .area .element {
    flex-shrink: 0;
  }

  #theia-statusBar::-webkit-scrollbar {
    display: block;
    height: 6px;
    width: auto;
  }

  #theia-statusBar::-webkit-scrollbar-thumb {
    background: var(--theia-scrollbarSlider-background, rgba(128, 128, 128, 0.45));
    border-radius: 3px;
  }

  #theia-statusBar::-webkit-scrollbar-track {
    background: transparent;
  }
}

/*-----------------------------------------------------------------------------
| Mobile snackbar (`mobile-snackbar.ts`).
|
| Single live region used by gestures with otherwise invisible side-effects
| (two-finger swipe between editor tabs, pull-to-refresh on sheets, …). Sits
| above the bottom activity bar / keyboard accessory so it stays readable.
| Solid backgrounds are the baseline; frosted glass applies when
| `backdrop-filter` is supported (and reduced-transparency is off).
|-----------------------------------------------------------------------------*/

.theia-mobile-snackbar {
  position: fixed;
  left: 50%;
  bottom: calc(var(--theia-mobile-bottom-chrome-reserved, 0px) + var(--theia-mobile-keyboard-inset, 0px) + 12px);
  transform: translate(-50%, 12px);
  /* Above parallel / agent-log overlays so run-start feedback stays readable. */
  z-index: 2147483020;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  max-width: min(92vw, 540px);
  padding: 10px 16px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 14%, transparent);
  background: var(--theia-notifications-background, var(--theia-editorWidget-background, #202020));
  color: var(--theia-notifications-foreground, var(--theia-foreground));
  box-shadow:
    0 10px 28px rgba(0, 0, 0, 0.30),
    0 1px 0 color-mix(in srgb, #fff 10%, transparent) inset;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
  pointer-events: none;
  opacity: 0;
  transition: transform 220ms cubic-bezier(.18, .89, .32, 1.12), opacity 200ms ease;
}

.theia-mobile-snackbar.theia-mod-visible {
  transform: translate(-50%, 0);
  opacity: 1;
  pointer-events: auto;
}

/* Top-anchored variant (narrow viewports only): outcome feedback for prompts that
 * drop from the top — e.g. the agent-CLI update toast — lands where the prompt was
 * instead of on the Work Hub composer, which owns the bottom edge there. */
@media (max-width: 767px) {
  .theia-mobile-snackbar.theia-mod-position-top {
    bottom: auto;
    top: calc(env(safe-area-inset-top, 0px) + 60px);
    transform: translate(-50%, -12px);
  }

  .theia-mobile-snackbar.theia-mod-position-top.theia-mod-visible {
    transform: translate(-50%, 0);
  }
}

.theia-mobile-snackbar.theia-mod-kind-success {
  background: var(--theia-debugConsole-infoForeground, #2c844a);
  border-color: color-mix(in srgb, var(--theia-debugConsole-infoForeground, #2c844a) 55%, #fff 20%);
  color: #fff;
}

.theia-mobile-snackbar.theia-mod-kind-warning {
  background: var(--theia-editorWarning-foreground, #cca700);
  border-color: color-mix(in srgb, var(--theia-editorWarning-foreground, #cca700) 55%, #1f1f1f 18%);
  color: #1f1f1f;
}

.theia-mobile-snackbar.theia-mod-kind-loading {
  background: var(--theia-notifications-background, var(--theia-editorWidget-background, #202020));
  color: var(--theia-notifications-foreground, var(--theia-foreground));
}

/* Frosted glass — same language as composer pills / bottom activity bar. */
@supports (backdrop-filter: blur(16px)) or (-webkit-backdrop-filter: blur(16px)) {

  .theia-mobile-snackbar,
  .theia-mobile-snackbar.theia-mod-kind-loading {
    background: color-mix(in srgb,
        var(--theia-notifications-background, var(--theia-editorWidget-background, #202020)) 58%,
        transparent);
    -webkit-backdrop-filter: blur(18px) saturate(150%);
    backdrop-filter: blur(18px) saturate(150%);
  }

  .theia-mobile-snackbar.theia-mod-kind-success {
    background: color-mix(in srgb, var(--theia-debugConsole-infoForeground, #2c844a) 58%, transparent);
    border-color: color-mix(in srgb, var(--theia-debugConsole-infoForeground, #2c844a) 48%, transparent);
    color: #fff;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.28);
