.theia-mobile-projects-variant-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--q-accent, var(--qaap-accent, #E58E40));
}

.theia-mobile-projects-variant-discard {
  border: none;
  background: transparent;
  color: var(--theia-descriptionForeground);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-projects-variant-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.theia-mobile-projects-variant-row>.theia-mobile-projects-task-row {
  flex: 1;
  min-width: 0;
}

.theia-mobile-projects-variant-side {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  margin-right: 4px;
  max-width: 42%;
}

.theia-mobile-projects-variant-state {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--theia-descriptionForeground);
}

.theia-mobile-projects-variant-state.theia-mod-idle {
  background: var(--theia-charts-green, #4caf7c);
}

.theia-mobile-projects-variant-state.theia-mod-failed {
  background: var(--theia-errorForeground, #f14c4c);
}

.theia-mobile-projects-variant-state.theia-mod-running {
  background: var(--q-accent, #E58E40);
  animation: theia-mobile-projects-pulse 1.4s ease-in-out infinite;
}

.theia-mobile-projects-variant-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 10px;
  line-height: 1.3;
  color: var(--theia-descriptionForeground);
  max-width: 100%;
}

.theia-mobile-projects-variant-running {
  font-size: 10px;
  font-weight: 600;
  color: var(--q-accent, var(--qaap-accent, #E58E40));
}

.theia-mobile-projects-variant-failed {
  font-size: 10px;
  font-weight: 600;
  color: var(--theia-errorForeground, #f14c4c);
}

.theia-mobile-projects-variant-run-status {
  margin-left: 6px;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-projects-variant-choose {
  flex: 0 0 auto;
  margin-right: 8px;
  border: none;
  border-radius: 8px;
  background: var(--q-accent, var(--qaap-accent, #E58E40));
  color: #1a1310;
  font-size: 12px;
  font-weight: 600;
  padding: 6px 12px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-projects-variant-choose:disabled {
  opacity: 0.5;
}

.theia-mobile-projects-variant-discard:disabled {
  opacity: 0.5;
  cursor: default;
}

.theia-mobile-agent-transcript-real-chat {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.theia-mobile-agent-transcript-real-chat>.theia-mobile-agent-transcript {
  flex: 1 1 auto;
  min-height: 0;
}

.theia-mobile-agent-transcript-real-chat .chat-view-widget,
.theia-mobile-agent-transcript-real-chat .theia-mobile-projects-real-agent-view {
  width: 100%;
  height: 100%;
  min-height: 0;
}

.theia-mobile-agent-transcript-real-chat .chat-tree-view-widget {
  min-height: 0;
}

.theia-mobile-agent-transcript-real-chat .chat-view-widget>.chat-input-widget {
  display: none !important;
}

/* Transcript type scale — one place to keep sizes consistent across cards, tools, and messages. */
.theia-mobile-agent-transcript-msg,
.theia-mobile-agent-transcript-empty {
  --qaap-tr-fs-body: 13px;
  --qaap-tr-fs-title: 13px;
  --qaap-tr-fs-meta: 11px;
  --qaap-tr-fs-micro: 10px;
  --qaap-tr-fs-head: 11px;
}

.theia-mobile-agent-transcript-empty {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  width: 100%;
  min-width: 0;
  max-width: none;
  box-sizing: border-box;
  margin-top: auto;
  padding: 0;
  text-align: left;
  overflow: hidden;
}

.theia-mobile-agent-transcript-empty-title {
  margin: 0;
  padding: 0 2px;
  font-family: var(--theia-ui-font-family, sans-serif);
  font-size: 13px;
  font-weight: var(--qaap-mobile-weight-title, 600);
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--theia-foreground);
}

.theia-mobile-agent-transcript.theia-mod-empty-chat {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  flex: 1 1 auto;
  min-height: 0;
  gap: 0;
  padding: clamp(24px, 8vh, 72px) 18px 96px;
}

.theia-mobile-agent-transcript.theia-mod-empty-chat:has(.theia-mod-transcript-recents) {
  justify-content: flex-start;
  align-items: stretch;
}

.theia-mobile-agent-transcript-empty-welcome {
  width: min(100%, 520px);
  margin: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.8vw, 14px);
  text-align: center;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
}

.theia-mobile-agent-transcript-empty-logo {
  width: clamp(48px, 8vw, 72px);
  height: clamp(48px, 8vw, 72px);
  margin-bottom: 2px;
  background-image: var(--theia-workbench-brand-logo-url);
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  opacity: 0.82;
  filter: drop-shadow(0 10px 28px color-mix(in srgb, var(--theia-foreground) 12%, transparent));
}

.theia-mobile-agent-transcript-empty-title {
  margin: 0;
  max-width: 14em;
  color: color-mix(in srgb, var(--theia-foreground) 90%, var(--theia-descriptionForeground));
  font-size: clamp(24px, 4.4vw, 36px);
  font-weight: 360;
  line-height: 1.14;
  letter-spacing: -0.012em;
  text-wrap: balance;
}

.theia-mobile-agent-transcript.theia-mod-empty-chat:has(.theia-mod-transcript-recents) .theia-mobile-agent-transcript-empty-welcome {
  margin: clamp(12px, 4vh, 32px) auto clamp(20px, 5vh, 40px);
  flex: 0 0 auto;
}

@media (max-width: 640px) {
  .theia-mobile-agent-transcript.theia-mod-empty-chat {
    padding: clamp(18px, 6vh, 52px) 16px 82px;
  }

  .theia-mobile-agent-transcript-empty-logo {
    width: 54px;
    height: 54px;
  }

  .theia-mobile-agent-transcript-empty-title {
    font-size: clamp(22px, 7vw, 30px);
  }
}

/*
 * Composer-hosted quick actions: the chip row lives inside the composer shell (above the card)
 * so it always tracks the composer's top border. Hidden by default; shown only when the composer
 * host carries .theia-mod-show-quick-actions (toggled by transcript render when the chat is empty).
 * Padding is zeroed because the composer shell already provides horizontal inset.
 */
.theia-mobile-projects-sticky-composer>.theia-mobile-agent-transcript-empty-actions {
  display: none;
  --qaap-empty-actions-edge-inset: 0;
  padding: 0 0 6px;
  padding-inline-start: 0;
  scroll-padding-inline-start: 0;
  scroll-padding-inline-end: 0;
}

.theia-mod-show-quick-actions .theia-mobile-projects-sticky-composer>.theia-mobile-agent-transcript-empty-actions {
  display: flex;
}

.theia-mobile-projects.theia-mod-sticky-composer:has(.theia-mobile-agent-transcript.theia-mod-empty-chat) .theia-mobile-projects-scroll {
  padding-bottom: 0;
}

.theia-mobile-agent-transcript-empty-actions {
  --qaap-empty-actions-edge-inset: max(16px, env(safe-area-inset-right, 0px));
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  margin: 0;
  padding: 0;
  padding-inline-start: max(16px, env(safe-area-inset-left, 0px));
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x proximity;
  scroll-padding-inline-start: max(16px, env(safe-area-inset-left, 0px));
  scroll-padding-inline-end: var(--qaap-empty-actions-edge-inset);
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x;
  overscroll-behavior-x: contain;
  box-sizing: border-box;
}

.theia-mobile-agent-transcript-empty-actions::after {
  content: '';
  flex: 0 0 var(--qaap-empty-actions-edge-inset);
  width: var(--qaap-empty-actions-edge-inset);
  height: 1px;
  scroll-snap-align: end;
  pointer-events: none;
}

.theia-mobile-agent-transcript-empty-actions::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

.theia-mobile-agent-transcript-empty-action {
  display: inline-flex;
  flex: 0 0 auto;
  flex-shrink: 0;
  flex-direction: row;
  align-items: center;
  gap: 5px;
  width: max-content;
  max-width: none;
  box-sizing: border-box;
  min-height: 30px;
  padding: 5px 10px 5px 7px;
  scroll-snap-align: start;
  border: 1px solid var(--q-line-soft, color-mix(in srgb, var(--theia-foreground) 8%, transparent));
  border-radius: var(--q-radius-pill, 99px);
  background: var(--q-surface-raised, color-mix(in srgb, var(--theia-foreground) 3%, transparent));
  color: var(--qaap-muted, var(--q-muted, var(--theia-descriptionForeground)));
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.2;
  text-align: left;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition: var(--qaap-mobile-state-transition);
}

.theia-mobile-agent-transcript-empty-action:last-of-type {
  scroll-snap-align: end;
}

.theia-mobile-agent-transcript-empty-action-icon {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border-radius: 0;
  background: transparent;
}

.theia-mobile-agent-transcript-empty-action .codicon {
  flex: 0 0 auto;
  font-size: 12px;
  color: inherit;
  opacity: 0.78;
}

.theia-mobile-agent-transcript-empty-action-label {
  flex: 0 0 auto;
  white-space: nowrap;
  color: inherit;
}

.theia-mobile-agent-transcript-empty-action:active {
  opacity: 0.76;
  background: var(--q-surface-raised, color-mix(in srgb, var(--theia-foreground) 3%, transparent));
  border-color: color-mix(in srgb, var(--theia-foreground) 12%, transparent);
}

.theia-mobile-agent-transcript-empty-action:hover,
.theia-mobile-agent-transcript-empty-action:focus-visible {
  background: color-mix(in srgb, var(--theia-foreground) 5%, transparent);
  border-color: color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  color: var(--qaap-muted, var(--q-muted, var(--theia-descriptionForeground)));
}

.theia-mobile-agent-transcript-empty-action:focus-visible {
  outline: 0.5px solid var(--theia-focusBorder);
  outline-offset: 2px;
}

.theia-mobile-agent-transcript-msg {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: var(--qaap-mobile-pad-row-y, 10px) var(--qaap-mobile-pad-row-x, 12px);
  border-radius: var(--qaap-mobile-radius-card, 12px);
  background: var(--theia-editorWidget-background, rgba(127, 127, 127, 0.08));
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.18));
  font-size: 13px;
  line-height: 1.45;
}

.theia-mobile-agent-transcript-content.theia-mod-deferred-markdown,
.theia-mobile-agent-transcript-user-wrap[data-transcript-row-deferred] .theia-mobile-agent-transcript-content.theia-mod-deferred-markdown {
  color: var(--theia-descriptionForeground, rgba(127, 127, 127, 0.85));
  white-space: pre-wrap;
  overflow: hidden;
}

.theia-mobile-agent-tool-body.theia-mod-deferred-tool-body {
  min-height: 0;
}

.theia-mobile-agent-transcript-msg.theia-mod-new-message,
.theia-mobile-agent-transcript-user-wrap.theia-mod-new-message,
.theia-mobile-agent-segments.theia-mod-new-message {
  animation: theia-mobile-transcript-message-in 160ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes theia-mobile-transcript-message-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.theia-mobile-agent-transcript-msg.theia-mod-user {
  align-self: flex-end;
  max-width: 86%;
  padding: 9px 13px;
  border-radius:
    var(--qaap-mobile-radius-card, 12px) var(--qaap-mobile-radius-card, 12px) var(--qaap-mobile-radius-control, 8px) var(--qaap-mobile-radius-card, 12px);
  background: color-mix(in srgb, var(--q-accent, #E58E40) 16%, var(--theia-editorWidget-background, rgba(127, 127, 127, 0.08)));
  border: 1px solid color-mix(in srgb, var(--q-accent, #E58E40) 26%, transparent);
  color: var(--theia-foreground);
}

.theia-mobile-agent-transcript-user-attachments {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  width: 100%;
  margin-bottom: 6px;
}

.theia-mobile-agent-transcript-user-context-chips {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  width: 100%;
  margin-bottom: 6px;
}

.theia-mobile-agent-transcript-user-context-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  max-width: min(360px, 100%);
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  background: var(--theia-editorWidget-background, color-mix(in srgb, var(--theia-foreground) 6%, transparent));
  color: var(--theia-foreground);
}

.theia-mobile-agent-transcript-user-context-chip-icon {
  flex: 0 0 auto;
  font-size: 14px;
  opacity: 0.85;
}

.theia-mobile-agent-transcript-user-context-chip-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.2;
}

.theia-mobile-agent-transcript-user-attachment {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(320px, 100%);
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  background: var(--theia-editorWidget-background, color-mix(in srgb, var(--theia-foreground) 6%, transparent));
}

.theia-mobile-agent-transcript-user-attachment-thumb.theia-mod-loading::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg,
      color-mix(in srgb, var(--theia-foreground) 4%, transparent) 8%,
      color-mix(in srgb, var(--theia-foreground) 12%, transparent) 18%,
      color-mix(in srgb, var(--theia-foreground) 4%, transparent) 33%);
  background-size: 200% 100%;
  animation: qaap-sticky-image-preview-shimmer 1.1s ease-in-out infinite;
}

.theia-mobile-agent-transcript-user-attachment-thumb {
  position: relative;
  flex: 0 0 auto;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 10%, transparent);
  background: color-mix(in srgb, var(--theia-foreground) 4%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
}

.theia-mobile-agent-transcript-user-attachment-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  overflow: hidden;
}

/* Hide the alt-text glyph run while the thumb has no source (loading/missing). */
.theia-mobile-agent-transcript-user-attachment-image:not([src]) {
  visibility: hidden;
}

/* Preview-feedback rich card: numbered annotations sent from Annotate mode. */
.theia-mobile-agent-transcript-feedback-card {
  display: flex;
  flex-direction: column;
  width: min(420px, 100%);
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  background: var(--theia-editorWidget-background, color-mix(in srgb, var(--theia-foreground) 6%, transparent));
  color: var(--theia-foreground);
  overflow: hidden;
}

.theia-mobile-agent-transcript-feedback-header {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px;
  margin: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-transcript-feedback-header:hover {
  background: color-mix(in srgb, var(--theia-foreground) 5%, transparent);
}

.theia-mobile-agent-transcript-feedback-icon {
  flex: 0 0 auto;
  font-size: 14px;
  opacity: 0.85;
}

.theia-mobile-agent-transcript-feedback-heading {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1 1 auto;
  gap: 1px;
}

.theia-mobile-agent-transcript-feedback-title {
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-transcript-feedback-meta {
  font-size: 11px;
  line-height: 1.3;
  color: color-mix(in srgb, var(--theia-foreground) 62%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-transcript-feedback-chevron {
  flex: 0 0 auto;
  font-size: 14px;
  opacity: 0.7;
  transition: transform 0.18s ease;
}

.theia-mobile-agent-transcript-feedback-card.theia-mod-collapsed .theia-mobile-agent-transcript-feedback-chevron {
  transform: rotate(-90deg);
}

.theia-mobile-agent-transcript-feedback-list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid color-mix(in srgb, var(--theia-foreground) 8%, transparent);
}

.theia-mobile-agent-transcript-feedback-card.theia-mod-collapsed .theia-mobile-agent-transcript-feedback-list {
  display: none;
}

.theia-mobile-agent-transcript-feedback-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
}

.theia-mobile-agent-transcript-feedback-item+.theia-mobile-agent-transcript-feedback-item {
  border-top: 1px solid color-mix(in srgb, var(--theia-foreground) 6%, transparent);
}

.theia-mobile-agent-transcript-feedback-index {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin-top: 1px;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
  color: var(--theia-button-foreground, #fff);
  background: var(--theia-button-background, color-mix(in srgb, var(--theia-foreground) 60%, transparent));
}

.theia-mobile-agent-transcript-feedback-item-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1 1 auto;
  gap: 6px;
}

.theia-mobile-agent-transcript-feedback-comment {
  font-size: 13px;
  line-height: 1.4;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.theia-mobile-agent-transcript-feedback-item-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.theia-mobile-agent-transcript-feedback-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  padding: 2px 8px;
  margin: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 10%, transparent);
  background: color-mix(in srgb, var(--theia-foreground) 5%, transparent);
  color: color-mix(in srgb, var(--theia-foreground) 78%, transparent);
  font-size: 11px;
  font-family: var(--theia-code-font-family, monospace);
  line-height: 1.5;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-transcript-feedback-tag .codicon {
  font-size: 12px;
}

button.theia-mobile-agent-transcript-feedback-tag {
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-family: var(--theia-code-font-family, monospace);
}

button.theia-mobile-agent-transcript-feedback-tag:hover {
  background: color-mix(in srgb, var(--theia-foreground) 10%, transparent);
  color: var(--theia-foreground);
}

.theia-mobile-agent-transcript-feedback-tag.theia-mod-selector {
  max-width: 220px;
}

.theia-mobile-agent-transcript-feedback-tag.theia-mod-unresolved {
  color: var(--theia-editorWarning-foreground, var(--theia-foreground));
  border-color: color-mix(in srgb, var(--theia-editorWarning-foreground, var(--theia-foreground)) 35%, transparent);
  font-family: inherit;
}

.theia-mobile-agent-transcript-content.theia-mod-user-skill-invocation {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  color: var(--theia-foreground);
  font-size: 15px;
  line-height: 1.45;
  font-weight: 500;
}

/* Skill mark in transcript: colored letters only — no pill/chip. */
.theia-mobile-agent-transcript-skill-pill {
  display: inline;
  align-items: unset;
  min-height: 0;
  padding: 0;
  margin: 0;
  border: none;
  border-radius: 0;
  background: transparent !important;
  background-image: none !important;
  background-color: transparent !important;
  color: #FFD89A;
  -webkit-text-fill-color: #FFD89A;
  font-weight: 700;
  line-height: inherit;
  box-shadow: none !important;
}

body.qaap-theme-light .theia-mobile-agent-transcript-skill-pill {
  background: transparent !important;
  background-image: none !important;
  background-color: transparent !important;
  color: #6B3F08;
