@media (hover: hover) and (pointer: fine) {

  .theia-mobile-agent-transcript-user-wrap:hover .theia-mobile-agent-transcript-user-actions,
  .theia-mobile-agent-transcript-user-wrap:focus-within .theia-mobile-agent-transcript-user-actions {
