  }
}

@media (hover: none),
(pointer: coarse) {
  .theia-mobile-agent-transcript-user-actions {
    opacity: 1;
    pointer-events: auto;
  }

  .theia-mobile-agent-transcript-user-action-label {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
