}

.theia-mobile-agent-transcript-msg.theia-mod-agent:not(.theia-mobile-agent-activity) {
  width: calc(100% + 2 * var(--theia-mobile-work-hub-pad-x, 16px));
  max-width: none;
  margin-right: calc(-1 * var(--theia-mobile-work-hub-pad-x, 16px));
  margin-left: calc(-1 * var(--theia-mobile-work-hub-pad-x, 16px));
  padding-top: 8px;
  padding-right: var(--theia-mobile-work-hub-pad-x, 16px);
  padding-bottom: 14px;
  padding-left: var(--theia-mobile-work-hub-pad-x, 16px);
  border: none;
  border-radius: 0;
  background: transparent;
}

.theia-mobile-agent-transcript-msg.theia-mod-streaming {
  opacity: 1;
  font-style: normal;
}

.theia-mobile-agent-transcript-msg.theia-mobile-agent-activity {
  width: calc(100% - 12px);
  max-width: none;
  margin: 8px 6px 18px;
  gap: 16px;
  padding: 22px 24px 20px;
  border-radius: 20px;
  border-color: color-mix(in srgb, var(--qaap-accent, #E58E40) 54%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--qaap-accent, #E58E40) 8%, transparent), transparent 44%),
    color-mix(in srgb, var(--theia-editor-background, #0b0b0a) 84%, #1c130d);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--qaap-accent, #E58E40) 10%, transparent);
}

.theia-mobile-agent-transcript-msg.theia-mobile-agent-activity .theia-mobile-agent-transcript-role {
  color: color-mix(in srgb, var(--theia-foreground) 72%, var(--theia-descriptionForeground));
  font-size: 14px;
  font-weight: 760;
  letter-spacing: 0.02em;
  opacity: 1;
}

/* Single live "thinking/acting" streaming line. */
.theia-mobile-agent-transcript-msg.theia-mobile-agent-activity {
  background: none;
  border: none;
  box-shadow: none;
  padding: 2px 0;
}

.theia-mobile-agent-stream-line {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 22px;
}

.theia-mobile-agent-stream-bootstrap {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 10px;
  padding-left: 17px;
}

.theia-mobile-agent-stream-bootstrap-step {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  line-height: 1.35;
}

.theia-mobile-agent-stream-bootstrap-step.theia-mod-success {
  color: color-mix(in srgb, var(--theia-foreground) 72%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-stream-bootstrap-step.theia-mod-running,
.theia-mobile-agent-stream-bootstrap-step.theia-mod-warning {
  color: var(--theia-foreground);
  font-weight: 500;
}

.theia-mobile-agent-stream-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--q-accent, #E58E40);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--q-accent, #E58E40) 55%, transparent);
}

.theia-mobile-agent-stream-line:has(.theia-mobile-agent-stream-label.theia-mod-shimmer) .theia-mobile-agent-stream-dot {
  animation: theia-mobile-agent-stream-ping 1.5s ease-out infinite;
}

.theia-mobile-agent-stream-line.theia-mod-thinking .theia-mobile-agent-stream-dot {
  background: var(--theia-focusBorder, #4c9aff);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--theia-focusBorder, #4c9aff) 55%, transparent);
}

.theia-mobile-agent-stream-label {
  overflow: hidden;
  font-size: var(--qaap-tr-fs-body, 13px);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-stream-label.theia-mod-shimmer {
  background: linear-gradient(100deg,
      var(--theia-descriptionForeground) 0%,
      var(--theia-foreground) 50%,
      var(--theia-descriptionForeground) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: theia-mobile-agent-stream-shimmer 2.1s linear infinite;
}

/* Light theme: --theia-foreground is near-black (#111) so the shimmer "bright"
   peak becomes a darkening sweep — wrong direction for a light background.
   Override with a lightening sweep: ink-2 (dark base) → muted (lighter peak),
   analogous to dark mode's gray → off-white → gray brightening sweep. */
body.qaap-theme-light .theia-mobile-agent-stream-label {
  color: var(--qaap-ink-2, #3A3A3A);
}

body.qaap-theme-light .theia-mobile-agent-stream-label.theia-mod-shimmer {
  background: linear-gradient(100deg,
      var(--qaap-ink-2, #3A3A3A) 0%,
      var(--qaap-muted, #8A8A8A) 50%,
      var(--qaap-ink-2, #3A3A3A) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: theia-mobile-agent-stream-shimmer 2.1s linear infinite;
}

@keyframes theia-mobile-agent-stream-ping {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--q-accent, #E58E40) 55%, transparent);
  }

  70%,
  100% {
    box-shadow: 0 0 0 7px transparent;
  }
}

@keyframes theia-mobile-agent-stream-shimmer {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}

.theia-mobile-agent-activity-body {
  display: grid;
  grid-template-columns: 50px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
}

.theia-mobile-agent-activity-pulse {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--qaap-accent, #E58E40) 58%, transparent);
  position: relative;
  box-shadow:
    inset 0 0 0 6px color-mix(in srgb, var(--qaap-accent, #E58E40) 10%, transparent),
    0 0 0 1px rgba(0, 0, 0, 0.35);
}

.theia-mobile-agent-activity-pulse::before,
.theia-mobile-agent-activity-pulse::after {
  content: '';
  position: absolute;
  inset: 9px;
  border-radius: inherit;
  background: var(--qaap-accent, #E58E40);
}

.theia-mobile-agent-activity-pulse::after {
  inset: -3px;
  background: transparent;
  border: 2px solid color-mix(in srgb, var(--qaap-accent, #E58E40) 36%, transparent);
  animation: theia-mobile-agent-activity-pulse 1.35s ease-out infinite;
}

.theia-mobile-agent-activity-copy {
  min-width: 0;
}

.theia-mobile-agent-activity-title {
  font-size: 18px;
  font-weight: 760;
  color: var(--theia-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  letter-spacing: 0;
}

.theia-mobile-agent-activity-detail {
  margin-top: 4px;
  font-size: 15px;
  font-weight: 560;
  color: var(--theia-descriptionForeground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  letter-spacing: 0;
}

.theia-mobile-agent-activity-steps {
