  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.28)) 80%, transparent);
  color: color-mix(in srgb, var(--theia-foreground) 62%, var(--theia-descriptionForeground));
  background: color-mix(in srgb, var(--theia-editor-background, #0b0b0a) 88%, #1b1b1b);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
  font-size: 14px;
  font-weight: 720;
  letter-spacing: 0;
}

.theia-mobile-agent-activity-step.theia-mod-active {
  color: var(--theia-foreground);
  border-color: color-mix(in srgb, var(--qaap-accent, #E58E40) 36%, transparent);
  background: color-mix(in srgb, var(--qaap-accent, #E58E40) 13%, var(--theia-editor-background, #0b0b0a));
}

@keyframes theia-mobile-agent-activity-pulse {
  0% {
    transform: scale(0.75);
    opacity: 0.75;
  }

  100% {
    transform: scale(1.45);
    opacity: 0;
  }
}

.theia-mobile-agent-transcript-role {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.7;
}

.theia-mobile-agent-transcript-content {
  white-space: pre-wrap;
  word-break: break-word;
}

.theia-mobile-agent-transcript-content.theia-mod-streaming-plain-text {
  font-family: var(--theia-code-font-family, ui-monospace, monospace);
  font-size: 14px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.theia-mobile-agent-transcript-content.theia-mod-streaming-incremental-markdown .theia-transcript-stream-frozen,
.theia-mobile-agent-transcript-content.theia-mod-streaming-incremental-markdown .theia-transcript-stream-tail {
  display: contents;
}

/*
 * Live suffix typography MUST match the rendered markdown body below
 * (.theia-mod-markdown: 15px / 1.58, proportional). This element holds the text the
 * markdown worker has not caught up to yet; when the worker lands, that text moves from
 * here into rendered markdown. Any font metric mismatch re-wraps the block to a different
 * line count on every patch, so the whole transcript below shifts — the visible "jump"
 * while streaming and while scrolling down through fresh content.
 */
.theia-mobile-agent-transcript-content.theia-mod-streaming-hybrid .theia-transcript-stream-plain-preview {
  /* Inherit rather than restate the numbers: several rules set the body type scale, so a
     hardcoded size here silently drifts out of match again. Inheriting from the content
     element is match-by-construction. */
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  white-space: pre-wrap;
  word-break: break-word;
}

.theia-mobile-agent-transcript-content.theia-mod-streaming-hybrid.theia-mod-markdown .theia-transcript-stream-plain-preview {
  margin-top: 0;
}

.theia-mobile-agent-transcript-content.theia-mod-streaming-hybrid .theia-transcript-stream-plain-preview[hidden] {
  display: none;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown {
