  overflow-x: auto;
  font-size: 15px;
  line-height: 1.58;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown>div> :first-child,
.theia-mobile-agent-transcript-content.theia-mod-markdown> :first-child {
  margin-top: 0;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown>div> :last-child,
.theia-mobile-agent-transcript-content.theia-mod-markdown> :last-child {
