.theia-mobile-agent-transcript-content.theia-mod-markdown ol {
  margin: 6px 0 12px;
  padding-left: 20px;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown li {
  margin: 4px 0;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown table {
  width: max-content;
  max-width: 100%;
  border-collapse: collapse;
  margin: 8px 0 12px;
  font-size: 12px;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown th,
.theia-mobile-agent-transcript-content.theia-mod-markdown td {
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.28));
  padding: 6px 8px;
  text-align: left;
  vertical-align: top;
}

.theia-mobile-agent-transcript-content.theia-mod-markdown th {
