  opacity: 0.82;
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-key {
  color: var(--theia-symbolIcon-propertyForeground, var(--theia-symbolIcon-keywordForeground, #9cdcfe));
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-string {
  color: var(--theia-symbolIcon-stringForeground, #ce9178);
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-number {
  color: var(--theia-symbolIcon-numberForeground, #b5cea8);
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-keyword {
  color: var(--theia-symbolIcon-functionForeground, var(--theia-symbolIcon-keywordForeground, #569cd6));
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-function {
  color: #dcdcaa;
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-parameter {
  color: #d7ba7d;
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-operator {
  color: color-mix(in srgb, var(--theia-foreground) 78%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-comment {
  color: var(--theia-symbolIcon-keywordForeground, #6a9955);
  opacity: 0.92;
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-path {
  color: var(--theia-textLink-foreground, #4fc1ff);
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-line {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 88%, var(--q-accent, #E58E40));
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-sep {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 70%, transparent);
}

.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-content,
.theia-mobile-agent-transcript-content .theia-mobile-agent-code-text .theia-mobile-agent-token.theia-mod-plain {
  color: var(--theia-foreground);
}

.theia-mobile-agent-transcript-content.theia-mod-markdown blockquote {
  margin: 8px 0 12px;
  padding: 2px 0 2px 10px;
  border-left: 3px solid var(--theia-panel-border, rgba(128, 128, 128, 0.35));
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-transcript-content.theia-mod-markdown a {
  color: var(--theia-textLink-foreground, var(--theia-focusBorder, #4c9aff));
}

.theia-mobile-agent-transcript-segments {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.theia-mobile-agent-transcript-segments>.theia-mobile-agent-transcript-content {
  margin-top: 2px;
}

.theia-mobile-agent-transcript-artifacts {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
  padding-top: 10px;
  border-top: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 42%, transparent);
}

.theia-mobile-agent-transcript-segments:not(:has(.theia-mobile-agent-transcript-content)) .theia-mobile-agent-transcript-artifacts {
  margin-top: 0;
  padding-top: 0;
  border-top: none;
}

/* Cursor-style thought header — collapsible summary line (no card chrome). */
.theia-mobile-agent-thought-brief {
  padding: 2px 0 6px;
  border: none;
  background: transparent;
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat>summary,
.theia-mobile-agent-thought-brief.theia-mod-cursor-flat>.theia-mobile-agent-thought-brief-summary {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 0;
  cursor: pointer;
  list-style: none;
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat>summary::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat>summary::before {
  display: none;
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat .theia-mobile-agent-thought-brief-head {
  display: none;
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat .theia-mobile-agent-thought-brief-title {
  font-size: 13px;
  font-weight: 600;
  color: color-mix(in srgb, var(--theia-foreground) 52%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat .theia-mobile-agent-thought-brief-body-wrap {
  margin-top: 4px;
  padding-left: 0;
  overflow: hidden;
  animation: theia-mobile-agent-thought-body-enter 200ms cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes theia-mobile-agent-thought-body-enter {
  from {
    opacity: 0;
    transform: translateY(-2px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.theia-mobile-agent-thought-brief.theia-mod-cursor-flat .theia-mobile-agent-thought-brief-body {
  font-size: 13px;
  line-height: 1.45;
  color: color-mix(in srgb, var(--theia-foreground) 88%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-thought-brief>summary {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  cursor: pointer;
  list-style: none;
  padding: 0;
}

.theia-mobile-agent-thought-brief>summary::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-thought-brief>summary::before {
  content: '';
  flex: none;
  width: 0;
  height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-left: 5px solid color-mix(in srgb, var(--theia-descriptionForeground) 70%, transparent);
  margin-right: 2px;
  transition: transform 120ms ease;
}

.theia-mobile-agent-thought-brief[open]>summary::before {
  transform: rotate(90deg);
}

.theia-mobile-agent-thought-brief-title {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: color-mix(in srgb, var(--theia-foreground) 58%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-thought-brief-title.theia-mod-shimmer {
  background: linear-gradient(100deg,
      color-mix(in srgb, var(--theia-descriptionForeground) 82%, var(--theia-foreground)) 0%,
      var(--theia-foreground) 50%,
      color-mix(in srgb, var(--theia-descriptionForeground) 82%, var(--theia-foreground)) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: theia-mobile-agent-stream-shimmer 2.1s linear infinite;
}

.theia-mobile-agent-thought-brief.theia-mod-thinking-live>summary .theia-mobile-agent-thought-brief-glyph {
  animation: theia-mobile-agent-thought-glyph-pulse 1.5s ease-out infinite;
}

.theia-mobile-agent-thought-brief-meta {
  font-size: 12px;
  line-height: 1.35;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 88%, var(--theia-foreground));
}

.theia-mobile-agent-thought-brief-body-wrap {
  margin-top: 6px;
  padding-left: 11px;
}

.theia-mobile-agent-thought-brief-body {
  margin: 4px 0 0;
  font-size: 13px;
  line-height: 1.45;
  letter-spacing: -0.01em;
  color: var(--theia-foreground);
}

.theia-mobile-agent-thought-brief-more {
  margin-top: 2px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 55%, transparent);
  background: color-mix(in srgb, var(--theia-editorWidget-background, rgba(127, 127, 127, 0.08)) 35%, transparent);
}

.theia-mobile-agent-thought-brief-more>summary {
  cursor: pointer;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 600;
  color: var(--theia-descriptionForeground);
  list-style: none;
}

.theia-mobile-agent-thought-brief-more>summary::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-thought-brief-more-body {
  margin: 8px 0 0;
  padding: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: var(--theia-ui-font-family, sans-serif);
  font-size: 12.5px;
  line-height: 1.45;
  color: color-mix(in srgb, var(--theia-foreground) 92%, var(--theia-descriptionForeground));
}

/* Tool UI-style tool cards — compact collapsible stack in the transcript artifacts strip. */
.theia-mobile-agent-tool-pills {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
  margin-bottom: 6px;
}

.theia-mobile-agent-tool-pill {
  flex: none;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border, color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 70%, transparent));
  background: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  box-shadow: 0 1px 2px color-mix(in srgb, var(--theia-widget-shadow, #000) 14%, transparent);
  font-size: 11px;
  letter-spacing: 0.01em;
  transition: box-shadow 0.15s ease, border-color 0.15s ease;
}

.theia-mobile-agent-tool-pill.theia-mod-done:not([open]) {
  box-shadow: none;
}

.theia-mobile-agent-tool-pill.theia-mod-failed {
  border-color: color-mix(in srgb, var(--theia-errorForeground, #f14c4c) 32%, var(--theia-widget-border, rgba(128, 128, 128, 0.24)));
}

.theia-mobile-agent-tool-pill-verb {
  flex: none;
  color: var(--theia-foreground);
  font-size: var(--qaap-tr-fs-title, 13px);
  font-weight: 600;
}

.theia-mobile-agent-tool-pill>summary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 8px 11px;
  cursor: pointer;
  list-style: none;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-tool-pill[open]>summary {
  border-bottom: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 70%, transparent);
}

.theia-mobile-agent-tool-pill>summary::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-tool-pill-summary .theia-mobile-agent-shell-tail {
  margin-left: auto;
}

.theia-mobile-agent-tool-pill-chevron {
  flex: none;
  color: var(--theia-descriptionForeground);
  font-size: 14px;
  transition: transform 140ms ease;
}

.theia-mobile-agent-tool-pill[open] .theia-mobile-agent-tool-pill-chevron {
  transform: rotate(90deg);
}

.theia-mobile-agent-tool-pill-icon {
  flex: none;
  font-size: 14px;
  color: color-mix(in srgb, var(--q-accent, #E58E40) 70%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-tool-pill-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  font-family: var(--theia-code-font-family, monospace);
  font-size: var(--qaap-tr-fs-meta, 11px);
  color: var(--theia-descriptionForeground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-tool-pill-badge {
  flex: none;
  padding: 1px 6px;
  border-radius: 4px;
  font-family: var(--theia-ui-font-family, sans-serif);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  line-height: 1.4;
}

.theia-mobile-agent-tool-pill-badge.theia-mod-mcp {
  color: color-mix(in srgb, var(--q-accent, #E58E40) 88%, var(--theia-foreground));
  background: color-mix(in srgb, var(--q-accent, #E58E40) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--q-accent, #E58E40) 28%, transparent);
}

.theia-mobile-agent-pill-terminal .theia-mobile-agent-shell-command-block {
  margin-bottom: 6px;
}

.theia-mobile-agent-pill-terminal .theia-mobile-agent-shell-output {
  margin: 0;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 11px;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
  color: color-mix(in srgb, var(--theia-foreground) 90%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-tool-pill.theia-mod-running .theia-mobile-agent-tool-pill-icon {
  animation: theia-tool-pill-icon-pulse 1.6s ease-in-out infinite;
}

@keyframes theia-tool-pill-icon-pulse {

  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.5;
  }
}

.theia-mobile-agent-tool-pill-body {
  padding: 9px 11px 11px;
  max-width: 100%;
  overflow-x: auto;
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-clamp {
  --qaap-clamp-fade-bg: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  margin-left: -11px;
  margin-right: -11px;
  width: calc(100% + 22px);
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-clamp-toggle {
  margin-bottom: -11px;
}

.theia-mobile-agent-tool-pill-speculative {
  height: 6px;
  margin: 4px 0 2px;
  border-radius: 999px;
  background: linear-gradient(90deg,
      color-mix(in srgb, var(--theia-descriptionForeground, #888) 18%, transparent) 0%,
      color-mix(in srgb, var(--theia-descriptionForeground, #888) 42%, transparent) 50%,
      color-mix(in srgb, var(--theia-descriptionForeground, #888) 18%, transparent) 100%);
  background-size: 200% 100%;
  animation: theia-transcript-tool-speculative-pulse 1.2s ease-in-out infinite;
}

@keyframes theia-transcript-tool-speculative-pulse {
  0% {
    background-position: 100% 0;
    opacity: 0.55;
  }

  50% {
    background-position: 0% 0;
    opacity: 1;
  }

  100% {
    background-position: 100% 0;
    opacity: 0.55;
  }
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-view {
  border-radius: 0;
  border: none;
  background: transparent;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-view.theia-mod-plain .theia-mobile-agent-code-gutter,
.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-view.theia-mod-shell .theia-mobile-agent-code-gutter {
  display: none;
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-view.theia-mod-plain .theia-mobile-agent-code-line,
.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-view.theia-mod-shell .theia-mobile-agent-code-line {
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  padding: 0;
  min-height: 1.5em;
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-line:hover {
  background: transparent;
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-text {
  font-size: 11px;
  line-height: 1.5;
  color: color-mix(in srgb, var(--theia-foreground) 90%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-tool-pill-body .theia-mobile-agent-code-gutter {
  font-size: 10px;
  opacity: 0.5;
}

.theia-mobile-agent-tool-pill.theia-mod-running .theia-mobile-agent-tool-pill-icon {
  color: var(--q-accent, #E58E40);
}

.theia-mobile-agent-tool-pill.theia-mod-done .theia-mobile-agent-shell-state,
.theia-mobile-agent-tool-pill.theia-mod-running .theia-mobile-agent-shell-state,
.theia-mobile-agent-tool-pill.theia-mod-failed .theia-mobile-agent-shell-state {
  opacity: 1;
}

.theia-mobile-agent-tool-pill.theia-mod-done .theia-mobile-agent-shell-state {
  background: var(--theia-charts-green, #4caf7c);
}

.theia-mobile-agent-tool-pill.theia-mod-running .theia-mobile-agent-shell-state {
  background: var(--q-accent, #E58E40);
  animation: theia-mobile-projects-pulse 1.4s ease-in-out infinite;
}

.theia-mobile-agent-tool-pill.theia-mod-failed .theia-mobile-agent-shell-state {
  background: var(--theia-errorForeground, #f14c4c);
}

/* Inline diff preview for edit tools (3–6 lines, GitHub-style). */
/* Claude-Code-style collapsed tool activity group: "Ran 4 commands, read 6 files ›". */
.theia-mobile-agent-tool-group {
  margin-bottom: 6px;
}

.theia-mobile-agent-tool-group-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  cursor: pointer;
  list-style: none;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--theia-descriptionForeground);
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-tool-group-head::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-tool-group-chevron {
  flex: none;
  font-size: 11px;
  opacity: 0.62;
  transition: transform 0.15s ease;
}

.theia-mobile-agent-tool-group[open]>.theia-mobile-agent-tool-group-head .theia-mobile-agent-tool-group-chevron {
  transform: rotate(90deg);
}

.theia-mobile-agent-tool-group-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-tool-group[open]>.theia-mobile-agent-tool-pills {
  padding: 6px 0 0;
}

/* Tool UI code-diff card — file edits with +/− stats and copy (ported from tool-ui.com). */
.theia-mobile-agent-diff-card {
  margin: 4px 0 10px;
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border, color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 70%, transparent));
  background: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  box-shadow: 0 1px 2px color-mix(in srgb, var(--theia-widget-shadow, #000) 14%, transparent);
}

.theia-mobile-agent-diff-card.theia-mod-done:not([open]) {
  box-shadow: none;
}

.theia-mobile-agent-diff-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 8px 11px;
  cursor: pointer;
  list-style: none;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-diff-card-head::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-diff-card-head .theia-mobile-agent-shell-tail {
  margin-left: auto;
}

.theia-mobile-agent-diff-card-chevron {
  flex: none;
  color: var(--theia-descriptionForeground);
  font-size: 14px;
  transition: transform 140ms ease;
}

.theia-mobile-agent-diff-card[open]>.theia-mobile-agent-diff-card-head .theia-mobile-agent-diff-card-chevron {
  transform: rotate(90deg);
}

.theia-mobile-agent-diff-card[open]>.theia-mobile-agent-diff-card-head {
  border-bottom: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 70%, transparent);
}

.theia-mobile-agent-diff-card-icon-wrap {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  color: var(--theia-descriptionForeground);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 8%, transparent);
}

.theia-mobile-agent-diff-card-icon {
  font-size: 15px;
}

.theia-mobile-agent-diff-card-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--qaap-tr-fs-title, 13px);
  font-weight: 600;
  color: var(--theia-foreground);
}

.theia-mobile-agent-diff-card-stats {
  display: inline-flex;
  gap: 8px;
  flex: none;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.theia-mobile-agent-diff-card-added {
  color: var(--theia-gitDecoration-addedResourceForeground, #3fb950);
}

.theia-mobile-agent-diff-card-removed {
  color: var(--theia-gitDecoration-deletedResourceForeground, #f85149);
}

.theia-mobile-agent-diff-card-body {
  overflow: hidden;
  font-family: var(--theia-monospace-font-family, ui-monospace, monospace);
  font-size: 11.5px;
  line-height: 1.5;
}

.theia-mobile-agent-diff-card-path {
  padding: 7px 11px;
  font-size: 11px;
  font-weight: 500;
  color: var(--theia-descriptionForeground);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 4%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 60%, transparent);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-diff-card-lines {
  margin: 0;
  padding: 2px 0 4px;
}

.theia-mobile-agent-diff-card-line {
  display: flex;
  align-items: baseline;
}

.theia-mobile-agent-diff-card-lineno {
  flex: none;
  min-width: 34px;
  padding-right: 8px;
  text-align: right;
  font-size: 10.5px;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 70%, transparent);
  user-select: none;
}

.theia-mobile-agent-diff-card-marker {
  flex: none;
  width: 14px;
  text-align: center;
  user-select: none;
}

.theia-mobile-agent-diff-card-text {
  flex: 1 1 auto;
  min-width: 0;
  padding-right: 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.theia-mobile-agent-diff-card-line.theia-mod-add {
