  border-radius: 999px;
  padding: 2px 7px;
  font-size: 10px;
  font-weight: 800;
  text-align: center;
  color: var(--theia-descriptionForeground);
  background: color-mix(in srgb, var(--theia-editor-background, #111) 76%, var(--theia-foreground, #fff));
}

.theia-mobile-agent-verification-row.theia-mod-passed .theia-mobile-agent-verification-state {
  color: var(--theia-button-foreground, #fff);
  background: var(--theia-charts-green, #4caf7c);
}

.theia-mobile-agent-verification-row.theia-mod-failed .theia-mobile-agent-verification-state {
  color: var(--theia-button-foreground, #fff);
  background: var(--theia-errorForeground, #f14c4c);
}

.theia-mobile-agent-verification-row.theia-mod-running .theia-mobile-agent-verification-state {
  color: #1a1310;
  background: var(--q-accent, #E58E40);
}

.theia-mobile-agent-verification-command {
  overflow: hidden;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 12px;
  color: var(--theia-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-technical-details {
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 76%, transparent);
  background: color-mix(in srgb, var(--theia-editorWidget-background, rgba(127, 127, 127, 0.08)) 42%, transparent);
}

.theia-mobile-agent-technical-details>summary {
  cursor: pointer;
  padding: 9px 11px;
  color: var(--theia-descriptionForeground);
  font-size: 11px;
  font-weight: 700;
}

.theia-mobile-agent-technical-details-body {
  display: grid;
  gap: 8px;
  padding: 0 10px 10px;
}

.theia-mobile-agent-transcript-segment {
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--theia-editor-background, rgba(0, 0, 0, 0.15));
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.2));
}

.theia-mobile-agent-transcript-segment-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  opacity: 0.75;
  margin-bottom: 4px;
}

.theia-mobile-agent-transcript-segment-body,
.theia-mobile-agent-transcript-segment-args,
.theia-mobile-agent-transcript-segment-result {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
  line-height: 1.4;
  font-family: var(--theia-monospace-font-family, monospace);
}

.theia-mobile-agent-transcript-segment.theia-mod-thinking {
  opacity: 0.85;
  font-style: italic;
}

.theia-mobile-agent-transcript-segment.theia-mod-tool .theia-mobile-agent-transcript-segment-result {
  margin-top: 6px;
  opacity: 0.9;
  max-height: 120px;
  overflow: auto;
}

.theia-mobile-agent-transcript-details {
  margin: 4px 0;
  border-radius: 8px;
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.2));
  padding: 6px 8px;
  background: var(--theia-editor-background, rgba(0, 0, 0, 0.12));
}

.theia-mobile-agent-transcript-details summary {
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  list-style: disclosure-closed;
}

.theia-mobile-agent-transcript-details[open] summary {
  list-style: disclosure-open;
  margin-bottom: 6px;
}

.theia-mobile-agent-transcript-details pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 11px;
  font-family: var(--theia-monospace-font-family, monospace);
}

/* Tool UI-style card: solid surface, hairline border, soft shadow (ported from tool-ui.com). */
.theia-mobile-agent-tool-window {
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border, color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 70%, transparent));
  background: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  box-shadow: 0 1px 2px color-mix(in srgb, var(--theia-widget-shadow, #000) 14%, transparent);
}

.theia-mobile-agent-tool-window.theia-mod-static {
  border-color: color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 48%, transparent);
  background: color-mix(in srgb, var(--theia-editorWidget-background, rgba(127, 127, 127, 0.08)) 72%, transparent);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--theia-foreground, #fff) 4%, transparent) inset;
}

.theia-mobile-agent-read-line {
  display: flex;
  align-items: baseline;
  gap: 0.35em;
  padding: 2px 0 5px;
  margin: 0;
  font-size: 13px;
  line-height: 1.35;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-read-line.theia-mod-clickable {
  cursor: pointer;
}

.theia-mobile-agent-read-line-verb {
  flex: none;
  color: color-mix(in srgb, var(--theia-foreground) 78%, transparent);
  font-weight: 400;
}

.theia-mobile-agent-read-line-detail {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 12.5px;
  font-weight: 400;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-read-line.theia-mod-running .theia-mobile-agent-read-line-detail {
  opacity: 0.88;
}

.theia-mobile-agent-tool-head.theia-mod-clickable {
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-tool-head.theia-mod-clickable:active {
  background: color-mix(in srgb, var(--theia-foreground, #fff) 5%, transparent);
}

.theia-mobile-agent-tool-head.theia-mod-clickable .theia-mobile-agent-tool-file-name {
  color: var(--theia-textLink-foreground, var(--theia-foreground));
}

.theia-mobile-agent-tool-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 8px 11px;
  cursor: pointer;
  list-style: none;
}

.theia-mobile-agent-tool-window[open] .theia-mobile-agent-tool-head {
  border-bottom: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 70%, transparent);
}

.theia-mobile-agent-tool-head::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-tool-head:focus,
.theia-mobile-agent-shell-head:focus {
  outline: none;
}

.theia-mobile-agent-tool-head:focus-visible,
.theia-mobile-agent-shell-head:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--theia-focusBorder, #4c9aff) 54%, transparent);
}

.theia-mobile-agent-tool-chevron {
  flex: none;
  color: var(--theia-descriptionForeground);
  font-size: 14px;
  transition: transform 140ms ease;
}

.theia-mobile-agent-tool-window[open] .theia-mobile-agent-tool-chevron {
  transform: rotate(90deg);
}

.theia-mobile-agent-tool-icon {
  flex: none;
  font-size: 14px;
  color: color-mix(in srgb, var(--q-accent, #E58E40) 70%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-tool-title {
  flex: none;
  color: var(--theia-foreground);
  font-size: var(--qaap-tr-fs-title, 13px);
  font-weight: 600;
}

.theia-mobile-agent-tool-target {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  font-family: var(--theia-code-font-family, monospace);
  font-size: var(--qaap-tr-fs-meta, 11px);
  color: var(--theia-descriptionForeground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-tool-file-name {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  font-family: var(--theia-code-font-family, monospace);
  font-size: var(--qaap-tr-fs-title, 13px);
  font-weight: 650;
  color: var(--theia-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-tool-file-dir {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  font-family: var(--theia-code-font-family, monospace);
  font-size: var(--qaap-tr-fs-meta, 11px);
  color: var(--theia-descriptionForeground);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theia-mobile-agent-tool-file-dir::before {
  content: '·';
  margin: 0 5px;
  opacity: 0.55;
}

/* Header meta (line/match counts): plain mono tabular text, Tool UI style. */
.theia-mobile-agent-tool-badge {
  flex: none;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-agent-tool-badge.theia-mod-muted {
  opacity: 0.88;
}

.theia-mobile-agent-tool-head .theia-mobile-agent-shell-tail {
  margin-left: auto;
}

.theia-mobile-agent-tool-body {
  padding: 9px 11px 11px;
  overflow-x: auto;
}

/* Nested code output sits flush inside the card body (Tool UI terminal/code-block pattern). */
.theia-mobile-agent-tool-body .theia-mobile-agent-code-view {
  border: none;
  border-radius: 0;
  background: transparent;
}

.theia-mobile-agent-tool-body .theia-mobile-agent-clamp {
  --qaap-clamp-fade-bg: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  margin-left: -11px;
  margin-right: -11px;
  width: calc(100% + 22px);
}

.theia-mobile-agent-tool-body .theia-mobile-agent-clamp-toggle {
  margin-bottom: -11px;
}

.theia-mobile-agent-tool-window.theia-mod-failed {
  border-color: color-mix(in srgb, var(--theia-errorForeground, #f14c4c) 32%, var(--theia-widget-border, rgba(128, 128, 128, 0.24)));
}

.theia-mobile-agent-tool-result {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 12px;
  line-height: 1.45;
  color: var(--theia-foreground);
}

.theia-mobile-agent-code-view {
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.22)) 72%, transparent);
  background: color-mix(in srgb, var(--theia-editor-background, #111) 92%, transparent);
  overflow-x: auto;
}

.theia-mobile-agent-code-lines {
  display: grid;
  min-width: min-content;
}

.theia-mobile-agent-code-line {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  padding: 0 10px 0 6px;
  min-height: 1.45em;
}

.theia-mobile-agent-code-line:hover {
  background: color-mix(in srgb, var(--theia-foreground, #fff) 4%, transparent);
}

.theia-mobile-agent-code-gutter {
  flex: none;
  min-width: 2ch;
  padding-right: 2px;
  text-align: right;
  user-select: none;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 11px;
  line-height: 1.45;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 72%, transparent);
  opacity: 0.72;
}

.theia-mobile-agent-code-text {
  display: block;
  white-space: pre;
  word-break: normal;
  overflow-wrap: normal;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 12px;
  line-height: 1.45;
  color: var(--theia-foreground);
}

.theia-mobile-agent-token.theia-mod-key {
  color: var(--theia-symbolIcon-keywordForeground, #9cdcfe);
}

.theia-mobile-agent-token.theia-mod-string {
  color: var(--theia-symbolIcon-stringForeground, #ce9178);
}

.theia-mobile-agent-token.theia-mod-number {
  color: var(--theia-symbolIcon-numberForeground, #b5cea8);
}

.theia-mobile-agent-token.theia-mod-keyword {
  color: var(--theia-symbolIcon-keywordForeground, #569cd6);
}

.theia-mobile-agent-token.theia-mod-function {
  color: #dcdcaa;
}

.theia-mobile-agent-token.theia-mod-parameter {
  color: #d7ba7d;
}

.theia-mobile-agent-token.theia-mod-operator {
  color: color-mix(in srgb, var(--theia-foreground) 78%, var(--theia-descriptionForeground));
}

.theia-mobile-agent-token.theia-mod-comment {
  color: var(--theia-symbolIcon-keywordForeground, #6a9955);
  opacity: 0.92;
}

.theia-mobile-agent-token.theia-mod-path {
  color: var(--theia-textLink-foreground, #4fc1ff);
}

.theia-mobile-agent-token.theia-mod-line {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 88%, var(--q-accent, #E58E40));
}

.theia-mobile-agent-token.theia-mod-error {
  color: var(--theia-errorForeground, #f14c4c);
}

.theia-mobile-agent-token.theia-mod-sep {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 70%, transparent);
}

.theia-mobile-agent-token.theia-mod-content {
  color: var(--theia-foreground);
}

.theia-mobile-agent-token.theia-mod-plain {
  color: var(--theia-foreground);
}

/* Clamp long output (tool results, terminal output) to a few preview lines with expand/collapse. */
.theia-mobile-agent-clamp {
  position: relative;
  --qaap-clamp-fade-bg: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
}

.theia-mobile-agent-clamp:not(.theia-mod-expanded)>pre,
.theia-mobile-agent-clamp:not(.theia-mod-expanded)>.theia-mobile-agent-code-view {
  position: relative;
  max-height: calc(var(--qaap-clamp-lines, 4) * 1.45em + 0.25em);
  overflow: hidden;
}

.theia-mobile-agent-clamp:not(.theia-mod-expanded)>pre::after,
.theia-mobile-agent-clamp:not(.theia-mod-expanded)>.theia-mobile-agent-code-view::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2.4em;
  pointer-events: none;
  background: linear-gradient(to bottom,
      transparent 0%,
      color-mix(in srgb, var(--qaap-clamp-fade-bg) 42%, transparent) 55%,
      var(--qaap-clamp-fade-bg) 100%);
}

.theia-mobile-agent-shell-body .theia-mobile-agent-clamp {
  --qaap-clamp-fade-bg: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  margin-left: -11px;
  margin-right: -11px;
  width: calc(100% + 22px);
}

.theia-mobile-agent-shell-body .theia-mobile-agent-clamp-toggle {
  margin-bottom: -11px;
}

.theia-mobile-agent-clamp:not(.theia-mod-expanded)>.theia-mobile-agent-code-view .theia-mobile-agent-code-lines {
  overflow: hidden;
}

/* Full-width ghost expand/collapse bar under clamped output (Tool UI pattern). */
.theia-mobile-agent-clamp-toggle {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 8px;
  padding: 6px 9px;
  border: none;
  border-top: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.3)) 80%, transparent);
  border-radius: 0;
  background: transparent;
  color: var(--theia-descriptionForeground);
  font-size: var(--qaap-tr-fs-meta, 11px);
  font-weight: 500;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-clamp-toggle:active {
  background: color-mix(in srgb, var(--theia-foreground, #fff) 13%, transparent);
}

.theia-mobile-agent-clamp-chevron {
  font-size: 13px;
}

.theia-mobile-agent-shell-window {
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border, color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.22)) 92%, transparent));
  background: var(--theia-editorWidget-background, var(--theia-editor-background, #111));
  box-shadow: 0 1px 2px color-mix(in srgb, var(--theia-widget-shadow, #000) 14%, transparent);
}

/* Settled collapsed cards keep the card surface (Tool UI style) but drop the lift. */
.theia-mobile-agent-shell-window.theia-mod-done:not([open]),
.theia-mobile-agent-tool-window.theia-mod-done:not([open]) {
  box-shadow: none;
}

.theia-mobile-agent-shell-window.theia-mod-failed {
  border-color: color-mix(in srgb, var(--theia-errorForeground, #f14c4c) 32%, var(--theia-widget-border, rgba(128, 128, 128, 0.24)));
}

.theia-mobile-agent-shell-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 8px 11px;
  overflow: hidden;
  cursor: pointer;
  list-style: none;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-shell-window[open] .theia-mobile-agent-shell-head {
  border-bottom: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.2)) 70%, transparent);
}

.theia-mobile-agent-shell-head .theia-mobile-agent-shell-tail {
  margin-left: auto;
}

.theia-mobile-agent-shell-chevron {
  flex: none;
  color: var(--theia-descriptionForeground);
  font-size: 14px;
  transition: transform 140ms ease;
}

.theia-mobile-agent-shell-window[open] .theia-mobile-agent-shell-chevron {
  transform: rotate(90deg);
}

.theia-mobile-agent-shell-head::-webkit-details-marker {
  display: none;
}

.theia-mobile-agent-shell-icon-wrap {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  color: var(--theia-descriptionForeground);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 8%, transparent);
}

.theia-mobile-agent-shell-icon {
  font-size: 15px;
}

.theia-mobile-agent-shell-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  font-family: var(--theia-code-font-family, monospace);
  font-size: var(--qaap-tr-fs-meta, 11px);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--theia-foreground);
}

.theia-mobile-agent-shell-exit-code {
  flex: none;
  min-width: 22px;
  padding: 2px 6px;
  border-radius: 6px;
  font-family: var(--theia-code-font-family, monospace);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: center;
  color: var(--theia-charts-green, #4caf7c);
  background: color-mix(in srgb, var(--theia-charts-green, #4caf7c) 14%, transparent);
}

.theia-mobile-agent-shell-exit-code.theia-mod-failed {
  color: var(--theia-errorForeground, #f14c4c);
  background: color-mix(in srgb, var(--theia-errorForeground, #f14c4c) 14%, transparent);
}

.theia-mobile-agent-shell-tail {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 4px;
}

.theia-mobile-agent-shell-state {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--theia-descriptionForeground);
  opacity: 0.65;
}

.theia-mobile-agent-shell-window.theia-mod-done .theia-mobile-agent-shell-state,
.theia-mobile-agent-tool-window.theia-mod-done .theia-mobile-agent-shell-state {
  background: var(--theia-charts-green, #4caf7c);
}

.theia-mobile-agent-shell-window.theia-mod-running .theia-mobile-agent-shell-state,
.theia-mobile-agent-tool-window.theia-mod-running .theia-mobile-agent-shell-state {
  background: var(--q-accent, #E58E40);
  animation: theia-mobile-projects-pulse 1.4s ease-in-out infinite;
}

.theia-mobile-agent-shell-window.theia-mod-failed .theia-mobile-agent-shell-state,
.theia-mobile-agent-tool-window.theia-mod-failed .theia-mobile-agent-shell-state {
  background: var(--theia-errorForeground, #f14c4c);
}

.theia-mobile-agent-shell-copy {
  position: relative;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--theia-descriptionForeground);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-agent-shell-copy:hover,
.theia-mobile-agent-shell-copy:focus-visible {
  color: var(--theia-foreground);
  background: color-mix(in srgb, var(--theia-foreground, #fff) 8%, transparent);
}

.theia-mobile-agent-shell-copy.codicon::before {
  font-size: 14px;
}

.theia-mobile-agent-shell-copy-tip {
  position: absolute;
  top: calc(100% + 5px);
  right: 0;
  z-index: 2;
  padding: 4px 8px;
  border-radius: 6px;
  font-family: var(--theia-ui-font-family, sans-serif);
  font-size: 11px;
  font-weight: 650;
  line-height: 1.2;
  white-space: nowrap;
  color: var(--theia-editorWidget-foreground, var(--theia-foreground));
  background: var(--theia-editorWidget-background, var(--theia-sideBar-background));
  border: 1px solid var(--theia-editorWidget-border, var(--theia-panel-border, transparent));
  box-shadow: 0 6px 18px color-mix(in srgb, var(--theia-widget-shadow, #000) 28%, transparent);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-3px);
  transition: opacity 0.14s ease, transform 0.14s ease;
}

.theia-mobile-agent-shell-copy.theia-mod-copied .theia-mobile-agent-shell-copy-tip,
.theia-mobile-agent-shell-copy.theia-mod-copy-failed .theia-mobile-agent-shell-copy-tip {
  opacity: 1;
  transform: translateY(0);
}

