  --qaap-capability-mark-size: 6px;
  --qaap-capability-track-bg: #eeeeee;
  --qaap-capability-progress: #0d8cff;
  --qaap-capability-mark: #bdbdbd;
  --qaap-capability-mark-active: color-mix(in srgb, #0d8cff 72%, #fff);
  --qaap-capability-thumb-border: #d7d7d7;
  --qaap-capability-motion: 150ms cubic-bezier(0.2, 0.8, 0.2, 1);
  touch-action: none;
}

body.qaap-theme-dark .qaap-model-capability-slider {
  --qaap-capability-track-bg: color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  --qaap-capability-mark: color-mix(in srgb, var(--theia-foreground) 34%, transparent);
  --qaap-capability-thumb-border: color-mix(in srgb, var(--theia-foreground) 18%, transparent);
}

.qaap-model-capability-slider-track {
  position: relative;
  height: var(--qaap-capability-track-height);
  border-radius: 999px;
  background: var(--qaap-capability-track-bg);
  cursor: pointer;
  user-select: none;
}

.qaap-model-capability-slider-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 999px;
  background: var(--qaap-capability-progress);
  pointer-events: none;
  transition: width var(--qaap-capability-motion);
}

.qaap-model-capability-slider.theia-mod-dragging .qaap-model-capability-slider-fill {
  transition: none;
}

.qaap-model-capability-slider-marks {
  position: absolute;
  inset: 0 0 0 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 calc(var(--qaap-capability-thumb-size) / 2);
  pointer-events: none;
}

.qaap-model-capability-slider-mark {
  pointer-events: auto;
  width: 20px;
  height: 20px;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  touch-action: manipulation;
}

.qaap-model-capability-slider-mark::before {
  content: '';
  width: var(--qaap-capability-mark-size);
  height: var(--qaap-capability-mark-size);
  border-radius: 999px;
  background: var(--qaap-capability-mark);
  transition: background-color var(--qaap-capability-motion), transform var(--qaap-capability-motion);
}

.qaap-model-capability-slider-mark.theia-mod-filled::before {
  background: var(--qaap-capability-mark-active);
}

.qaap-model-capability-slider-mark.theia-mod-active::before {
  transform: scale(1.05);
}

.qaap-model-capability-slider-thumb {
  position: absolute;
  top: 50%;
  width: var(--qaap-capability-thumb-size);
  height: var(--qaap-capability-thumb-size);
  border-radius: 999px;
  border: 1px solid var(--qaap-capability-thumb-border);
  background: var(--theia-editorWidget-background, #fff);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.14);
  transform: translate(-50%, -50%);
  pointer-events: none;
  transition:
    left var(--qaap-capability-motion),
    transform var(--qaap-capability-motion),
    box-shadow 150ms ease;
}

.qaap-model-capability-slider:not(.theia-mod-dragging):hover .qaap-model-capability-slider-thumb {
  transform: translate(-50%, -50%) scale(1.04);
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.18);
}

.qaap-model-capability-slider.theia-mod-dragging .qaap-model-capability-slider-thumb {
  transition: none;
}

.qaap-model-capability-slider.theia-mod-keyboard-focus:focus-visible {
  outline: none;
}

.qaap-model-capability-slider.theia-mod-keyboard-focus .qaap-model-capability-slider-thumb {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--theia-focusBorder, #0d8cff) 34%, transparent),
    0 2px 8px rgba(0, 0, 0, 0.14);
}

@media (prefers-reduced-motion: reduce) {

  .qaap-sticky-composer-sheet-popover.theia-mod-model-capability,
  .theia-mobile-sticky-composer-sheet.theia-mod-model-capability {
    animation: none;
  }

  .qaap-model-capability-popover-bolt,
  .qaap-model-capability-popover-bolt.theia-mod-zap-strike,
  .qaap-model-capability-popover-bolt.theia-mod-zap-strike .qaap-model-capability-popover-bolt-path {
    animation: none;
  }

  .qaap-model-capability-slider {
    --qaap-capability-motion: 0ms;
  }

  .qaap-model-capability-slider:not(.theia-mod-dragging):hover .qaap-model-capability-slider-thumb {
    transform: translate(-50%, -50%);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.14);
  }

  .qaap-model-capability-slider-fill,
  .qaap-model-capability-slider-thumb,
  .qaap-model-capability-slider-mark::before {
    transition: none;
  }
}

