.theia-mobile-projects-sticky-composer-input-panel.theia-mod-agent-working,
.theia-mobile-projects-sticky-composer-card.theia-mod-has-context.theia-mod-agent-working,
.theia-mobile-sticky-composer-commit-group.theia-mod-busy,
.qaap-composer-improve-btn.theia-mod-busy {
  /* Defaults = tema oscuro (md.dark del paquete), strength 70% como el playground */
  --qaap-beam-strength: 0.7;
  --qaap-beam-stroke-opacity: 0.26;
  --qaap-beam-inner-opacity: 0.42;
  --qaap-beam-bloom-opacity: 0.24;
  --qaap-beam-saturation: 1.2;
  --qaap-beam-inner-shadow: rgba(255, 255, 255, 0.27);
  /* Highlight blanco que recorre el borde (cola larga y degradada) */
  --qaap-beam-highlight: conic-gradient(from var(--qaap-border-beam-angle),
      transparent 0%, transparent 54%,
      rgba(255, 255, 255, 0.1) 57%,
      rgba(255, 255, 255, 0.3) 60%,
      rgba(255, 255, 255, 0.6) 63%,
      rgba(255, 255, 255, 0.75) 66%,
      rgba(255, 255, 255, 0.6) 69%,
      rgba(255, 255, 255, 0.3) 72%,
      rgba(255, 255, 255, 0.1) 75%,
      transparent 78%, transparent 100%);
  /* Pico fino y brillante para el bloom desenfocado */
  --qaap-beam-bloom-gradient: conic-gradient(from var(--qaap-border-beam-angle),
      transparent 0%, transparent 58%,
      rgba(255, 255, 255, 0.03) 62%,
      rgba(255, 255, 255, 0.08) 65%,
      rgba(255, 255, 255, 0.2) 67%,
      rgba(255, 255, 255, 0.45) 69%,
      rgba(255, 255, 255, 0.85) 70%,
      rgba(255, 255, 255, 0.85) 70.5%,
      rgba(255, 255, 255, 0.45) 71.5%,
      rgba(255, 255, 255, 0.2) 73%,
      rgba(255, 255, 255, 0.08) 75%,
      rgba(255, 255, 255, 0.03) 78%,
      transparent 82%);
  /* Ventana cónica suave que revela ~65% del perímetro con colas degradadas */
  --qaap-beam-window: conic-gradient(from var(--qaap-border-beam-angle),
      transparent 0%, transparent 30%,
      rgba(255, 255, 255, 0.1) 36%, rgba(255, 255, 255, 0.35) 44%,
      white 52%, white 80%,
      rgba(255, 255, 255, 0.35) 86%, rgba(255, 255, 255, 0.1) 92%,
      transparent 95%, transparent 100%);
  position: relative;
  /* Giro lento y constante (linear evita tirones); el default del paquete es 1.96s */
