/* Capa 1 — stroke ring: blobs de color + highlight, recortado al anillo de 1px y a la ventana cónica */
.theia-mobile-projects-sticky-composer-input-panel.theia-mod-agent-working::after,
.theia-mobile-projects-sticky-composer-card.theia-mod-has-context.theia-mod-agent-working::after,
.theia-mobile-sticky-composer-commit-group.theia-mod-busy::after,
.qaap-composer-improve-btn.theia-mod-busy::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background:
    var(--qaap-beam-highlight),
    radial-gradient(ellipse 70px 40px at 33% -7.4%, rgb(255, 50, 100), transparent),
    radial-gradient(ellipse 60px 35px at 12% -5%, rgb(40, 140, 255), transparent),
    radial-gradient(ellipse 40px 70px at 2.1% 68.3%, rgb(50, 200, 80), transparent),
    radial-gradient(ellipse 20px 35px at 2.1% 68.3%, rgb(30, 185, 170), transparent),
    radial-gradient(ellipse 180px 32px at 74.4% 100%, rgb(100, 70, 255), transparent),
    radial-gradient(ellipse 85px 26px at 55% 100%, rgb(40, 140, 255), transparent),
    radial-gradient(ellipse 74px 32px at 93.9% 0%, rgb(255, 120, 40), transparent),
    radial-gradient(ellipse 26px 42px at 100% 27.1%, rgb(240, 50, 180), transparent),
    radial-gradient(ellipse 52px 48px at 100% 27.1%, rgb(180, 40, 240), transparent);
  -webkit-mask:
    var(--qaap-beam-window),
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: source-in, xor;
  mask:
    var(--qaap-beam-window),
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: intersect, exclude;
  pointer-events: none;
  z-index: 2;
  opacity: calc(var(--qaap-border-beam-opacity) * var(--qaap-beam-stroke-opacity) * var(--qaap-beam-strength));
  animation: qaap-border-beam-hue 12s ease-in-out infinite;
}

/* Capa 2 — lavado interior: mismos blobs al 45% / 0.9x, desvanecidos hacia el centro (franja de 28px) */
.theia-mobile-projects-sticky-composer-input-panel.theia-mod-agent-working::before,
.theia-mobile-projects-sticky-composer-card.theia-mod-has-context.theia-mod-agent-working::before,
