.qaap-composer-improve-btn.theia-mod-busy::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(ellipse 63px 36px at 33% -7.4%, rgba(255, 50, 100, 0.45), transparent),
    radial-gradient(ellipse 54px 32px at 12% -5%, rgba(40, 140, 255, 0.45), transparent),
    radial-gradient(ellipse 36px 63px at 2.1% 68.3%, rgba(50, 200, 80, 0.45), transparent),
    radial-gradient(ellipse 18px 32px at 2.1% 68.3%, rgba(30, 185, 170, 0.45), transparent),
    radial-gradient(ellipse 162px 29px at 74.4% 100%, rgba(100, 70, 255, 0.45), transparent),
    radial-gradient(ellipse 77px 23px at 55% 100%, rgba(40, 140, 255, 0.45), transparent),
    radial-gradient(ellipse 67px 29px at 93.9% 0%, rgba(255, 120, 40, 0.45), transparent),
    radial-gradient(ellipse 23px 38px at 100% 27.1%, rgba(240, 50, 180, 0.45), transparent),
    radial-gradient(ellipse 47px 43px at 100% 27.1%, rgba(180, 40, 240, 0.45), transparent);
  box-shadow: inset 0 0 9px 1px var(--qaap-beam-inner-shadow);
  -webkit-mask-image:
    var(--qaap-beam-window),
    linear-gradient(white, transparent 28px, transparent calc(100% - 28px), white),
    linear-gradient(to right, white, transparent 28px, transparent calc(100% - 28px), white);
  -webkit-mask-composite: source-in, source-over;
  mask-image:
    var(--qaap-beam-window),
    linear-gradient(white, transparent 28px, transparent calc(100% - 28px), white),
    linear-gradient(to right, white, transparent 28px, transparent calc(100% - 28px), white);
  mask-composite: intersect, add;
  pointer-events: none;
  z-index: 1;
  opacity: calc(var(--qaap-border-beam-opacity) * var(--qaap-beam-inner-opacity) * var(--qaap-beam-strength));
  animation: qaap-border-beam-hue 12s ease-in-out infinite;
}

/* Capa 3 — bloom: el pico del haz desenfocado, recortado al anillo */
.theia-mobile-projects-sticky-composer-input-panel .qaap-border-beam-bloom,
.theia-mobile-projects-sticky-composer-card.theia-mod-has-context .qaap-card-beam-bloom,
.theia-mobile-sticky-composer-commit-group .qaap-border-beam-bloom,
.qaap-composer-improve-btn .qaap-border-beam-bloom {
  display: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: var(--qaap-beam-bloom-gradient);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  filter: blur(8px) brightness(1.3) saturate(var(--qaap-beam-saturation));
  pointer-events: none;
  z-index: 3;
  opacity: 0;
}

.theia-mobile-projects-sticky-composer-input-panel.theia-mod-agent-working .qaap-border-beam-bloom,
.theia-mobile-projects-sticky-composer-card.theia-mod-has-context.theia-mod-agent-working .qaap-card-beam-bloom,
.theia-mobile-sticky-composer-commit-group.theia-mod-busy .qaap-border-beam-bloom,
.qaap-composer-improve-btn.theia-mod-busy .qaap-border-beam-bloom {
  display: block;
  opacity: calc(var(--qaap-border-beam-opacity) * var(--qaap-beam-bloom-opacity) * var(--qaap-beam-strength));
}

