  --theia-mobile-execution-header-block: calc(var(--theia-mobile-execution-header-pad-top) + var(--theia-mobile-execution-header-title-row) + var(--theia-mobile-execution-header-pad-bottom));
}

.qaap-work-hub-chat-view-widget .qaap-work-hub-chat-view-panel.theia-mod-project-surface-tools>.theia-mobile-projects-header {
  box-shadow: none;
}

.qaap-work-hub-chat-view-widget .qaap-work-hub-chat-view-panel.theia-mod-project-surface-tools>.theia-mobile-projects-sticky-composer,
.qaap-work-hub-chat-view-widget .qaap-work-hub-chat-view-panel.theia-mod-project-surface-tools .theia-mobile-projects-sticky-composer,
.qaap-work-hub-chat-view-widget .qaap-work-hub-chat-view-panel.theia-mod-project-surface-tools .theia-mobile-agent-transcript-empty-actions {
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.qaap-work-hub-chat-view-widget .qaap-work-hub-chat-view-panel.theia-mod-project-surface-tools.theia-mod-sticky-composer {
  display: flex;
}

.qaap-work-hub-chat-view-widget .qaap-work-hub-chat-view-panel.theia-mod-project-surface-tools>.theia-mobile-projects-scroll {
  flex: 1 1 auto !important;
  min-height: 0 !important;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
}

/* Agent execution timeline: narrative-first rows, with tools as collapsed secondary detail. */
.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item.theia-mod-narrative {
  display: block !important;
  grid-template-columns: none !important;
  min-height: 0 !important;
  padding: 14px 2px 7px 28px !important;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.theia-mobile-agent-activity-timeline.theia-mod-cursor-trace.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item.theia-mod-narrative {
  display: block !important;
  grid-template-columns: none !important;
  min-height: 0 !important;
  padding: 14px 2px 7px 28px !important;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item.theia-mod-narrative::before {
  display: none;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item.theia-mod-narrative .theia-mobile-agent-activity-copy {
  display: block !important;
  grid-column: 1 / -1 !important;
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0;
}

.theia-mobile-agent-activity-timeline.theia-mod-cursor-trace.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item.theia-mod-narrative .theia-mobile-agent-activity-copy {
  display: block !important;
  grid-column: 1 / -1 !important;
  width: 100% !important;
  max-width: 100% !important;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-narrative {
  margin: 0;
  color: var(--theia-descriptionForeground);
  font-size: 13px;
  line-height: 1.55;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item.theia-mod-toolGroup,
.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-item:has(.theia-mobile-agent-activity-verb) {
  border-radius: 6px;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-icon {
  opacity: .62;
  transform: scale(.86);
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-row {
  gap: 6px;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-verb {
  font-weight: 560;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-verb+.theia-mobile-agent-activity-detail {
  margin-left: 4px;
}

.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-detail:not(.theia-mod-pill),
.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-tail,
.theia-mobile-agent-lobe-workflow .theia-mobile-agent-activity-meta {
  color: var(--theia-descriptionForeground);
}

/* ─── Codex-style Execution Event Timeline (mobile) ───────────────────────── */
/* Replaces the old activity timeline + tool pills + diff/verification cards.  */
/* Events are the primary element; tools are children, not siblings.           */
/* Everything collapsed by default. Only Terminal/Error/Diff get cards.        */

.theia-mobile-execution-timeline {
  display: flex;
  flex-direction: column;
}

/* ─── ProcessAccordion: the single collapsible for all process steps ──────── */
/* Codex-style process header — no bottom rule; live turn footer is chrome-free. */
/* Auto-expands while working, auto-collapses on success, open on error.       */

.theia-mobile-process-accordion {
  margin: 0 0 20px 0;
  border-bottom: none;
}

.theia-mobile-process-accordion-header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  padding: 0 0 8px 0;
  list-style: none;
  cursor: pointer;
  user-select: none;
}

.theia-mobile-process-accordion-header::-webkit-details-marker {
  display: none;
}

/* Orb belongs in the pinned stream footer, not the accordion header. */
.theia-mobile-process-accordion-header .theia-mobile-process-accordion-logo,
.theia-mobile-process-accordion-header .qaap-thinking-orb-indicator {
  display: none !important;
}

.theia-mobile-process-accordion-label {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-weight: 500;
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Which agent/model ran this turn lives ABOVE the accordion (see
   .theia-mobile-turn-provenance-standalone), never inside the summary. Legacy
   header-hosted badges are cleared in JS; these rules are inert safety nets. */
.theia-mobile-process-accordion-header .theia-mobile-process-accordion-provenance {
  display: none !important;
}

/* Turn-provenance badge: agent avatar + provider sub-icon + model label.
   Mounted as the first child of the segments body, above the process accordion
   (or above thought/text when there is no accordion). Uses the full transcript
   line width — truncate with ellipsis only when the name approaches the
   viewport edge, never with an artificial ch cap. */
.theia-mobile-turn-provenance-standalone {
  display: flex;
  align-items: center;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 28px;
  margin: 0 0 8px 0;
  box-sizing: border-box;
}

.theia-mobile-turn-provenance-standalone.theia-qaap-agent-identity,
.theia-mobile-turn-provenance-standalone .theia-qaap-agent-identity {
  flex: 1 1 auto;
  min-width: 0;
  max-width: 100%;
}

.theia-mobile-turn-provenance-standalone .theia-qaap-agent-identity-label {
  flex: 1 1 auto;
  min-width: 0;
  max-width: none;
}

.theia-mobile-process-accordion.theia-mod-working .theia-mobile-process-accordion-label {
  color: var(--theia-foreground);
}

.theia-mobile-process-accordion.theia-mod-error .theia-mobile-process-accordion-label {
  color: var(--theia-errorForeground);
}

.theia-mobile-process-accordion.theia-mod-cancelled .theia-mobile-process-accordion-label {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 65%, transparent);
}

.theia-mobile-process-accordion-chevron {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  opacity: 0.72;
  transition: transform 200ms ease;
  flex: 0 0 auto;
}

.theia-mobile-process-accordion[open] .theia-mobile-process-accordion-chevron {
  transform: rotate(180deg);
}

.theia-mobile-process-accordion-content {
  padding-top: 4px;
}

/* ─── Slow-turn hint: subtle nudge once a turn runs long ──────────────────── */
/* Sits right after the process accordion (never inside it), so it stays out  */
/* of the streaming patch/rebuild paths and is unaffected by open/collapse.   */

.theia-mobile-slow-turn-hint {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: -12px 0 20px 0;
  color: var(--theia-descriptionForeground);
  font-size: 11px;
  line-height: 1.4;
}

.theia-mobile-slow-turn-hint-icon {
  flex-shrink: 0;
  font-size: 12px;
  opacity: 0.85;
}

.theia-mobile-slow-turn-hint-text {
  flex: 1 1 auto;
  min-width: 0;
}

.theia-mobile-slow-turn-hint-stop {
  flex-shrink: 0;
  padding: 2px 8px;
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.35));
  border-radius: 6px;
  background: transparent;
  color: var(--theia-foreground);
  font-size: 11px;
  line-height: 1.4;
  cursor: pointer;
}

.theia-mobile-slow-turn-hint-stop:hover,
.theia-mobile-slow-turn-hint-stop:focus-visible {
  background: var(--theia-toolbar-hoverBackground);
  outline: none;
}

.theia-mobile-slow-turn-hint-dismiss {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  min-width: 20px;
  min-height: 20px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--theia-descriptionForeground);
  font-size: 11px;
  cursor: pointer;
}

.theia-mobile-slow-turn-hint-dismiss:hover,
.theia-mobile-slow-turn-hint-dismiss:focus-visible {
  background: var(--theia-toolbar-hoverBackground);
  color: var(--theia-foreground);
  outline: none;
}

/* ─── ExecutionEvent: one narrative + one tool group ──────────────────────── */
/* Much air between events, little air within.                                 */

.theia-mobile-execution-event {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-bottom: 24px;
}

.theia-mobile-execution-event:last-child {
  padding-bottom: 0;
}

/* ─── Narrative: the story text that leads each event ─────────────────────── */

.theia-mobile-execution-event-narrative {
  margin: 0;
  color: var(--theia-foreground);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.6;
}

.theia-mobile-execution-event-narrative.theia-mod-synthetic {
  color: color-mix(in srgb, var(--theia-foreground) 60%, var(--theia-descriptionForeground) 40%);
  font-weight: 400;
  font-style: italic;
}

/* ─── ToolGroup: collapsed by default, one-line summary ───────────────────── */

.theia-mobile-tool-group {
  margin: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  overflow: hidden;
  transition: background-color 180ms ease;
}

.theia-mobile-tool-group:hover {
  background: color-mix(in srgb, var(--theia-foreground) 4%, transparent);
}

.theia-mobile-tool-group-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 0 8px;
  list-style: none;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-tool-group-summary::-webkit-details-marker {
  display: none;
}

.theia-mobile-tool-group-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--theia-descriptionForeground);
  font-size: 14px;
  opacity: 0.68;
  transform-origin: center center;
  will-change: auto;
}

/* lucide-animated–inspired continuous motion while a tool group / activity
   icon is in progress. Class toggled via syncActivityToolIconMotion(). */
.theia-mobile-tool-group-icon.theia-mod-tool-motion,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion {
  will-change: transform, opacity;
}

.theia-mobile-tool-group.running .theia-mobile-tool-group-icon.theia-mod-tool-motion {
  opacity: 0.92;
  color: color-mix(in srgb, var(--theia-foreground) 82%, var(--theia-descriptionForeground));
}

@keyframes qaap-tool-icon-motion-edit {

  0%,
  100% {
    transform: translate(0, 0) rotate(0deg);
  }

  25% {
    transform: translate(-0.5px, 1px) rotate(-10deg);
  }

  50% {
    transform: translate(1px, -0.5px) rotate(8deg);
  }

  75% {
    transform: translate(-0.5px, 0.5px) rotate(-4deg);
  }
}

@keyframes qaap-tool-icon-motion-write {

  0%,
  100% {
    transform: scale(1);
  }

  35% {
    transform: scale(1.12);
  }

  55% {
    transform: scale(0.94);
  }
}

@keyframes qaap-tool-icon-motion-search {

  0%,
  100% {
    transform: translate(0, 0);
  }

  30% {
    transform: translate(0, -2px);
  }

  55% {
    transform: translate(-2px, 0);
  }
}

@keyframes qaap-tool-icon-motion-read {

  0%,
  100% {
    transform: scale(1);
    opacity: 0.88;
  }

  40% {
    transform: scale(1.06);
    opacity: 1;
  }

  70% {
    transform: scale(0.98);
    opacity: 0.72;
  }
}

@keyframes qaap-tool-icon-motion-update {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes qaap-tool-icon-motion-run {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-1.5px);
  }
}

@keyframes qaap-tool-icon-motion-delete {

  0%,
  100% {
    transform: translateX(0);
  }

  20% {
    transform: translateX(-1.5px);
  }

  40% {
    transform: translateX(1.5px);
  }

  60% {
    transform: translateX(-1px);
  }

  80% {
    transform: translateX(1px);
  }
}

@keyframes qaap-tool-icon-motion-generic {

  0%,
  100% {
    opacity: 0.72;
    transform: scale(1);
  }

  50% {
    opacity: 1;
    transform: scale(1.05);
  }
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-edit,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-edit {
  animation: qaap-tool-icon-motion-edit 0.85s ease-in-out infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-write,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-write {
  animation: qaap-tool-icon-motion-write 1.05s ease-in-out infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-search,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-search {
  animation: qaap-tool-icon-motion-search 1s ease-in-out infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-read,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-read {
  animation: qaap-tool-icon-motion-read 1.35s ease-in-out infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-update,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-update {
  animation: qaap-tool-icon-motion-update 1.1s linear infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-run,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-run {
  animation: qaap-tool-icon-motion-run 0.9s ease-in-out infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-delete,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-delete {
  animation: qaap-tool-icon-motion-delete 0.55s ease-in-out infinite;
}

.theia-mobile-tool-group-icon.theia-mod-tool-motion-generic,
.theia-mobile-agent-activity-icon.theia-mod-tool-motion-generic {
  animation: qaap-tool-icon-motion-generic 1.4s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {

  .theia-mobile-tool-group-icon.theia-mod-tool-motion,
  .theia-mobile-agent-activity-icon.theia-mod-tool-motion,
  .theia-mobile-tool-group-icon[class*="theia-mod-tool-motion-"],
  .theia-mobile-agent-activity-icon[class*="theia-mod-tool-motion-"] {
    animation: none !important;
  }
}

.theia-mobile-tool-group-verb {
  font-weight: 500;
  font-size: 13px;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-tool-group-meta {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-weight: 400;
  opacity: 0.72;
}

.theia-mobile-tool-group.running .theia-mobile-tool-group-verb.theia-mod-shimmer,
.theia-mobile-tool-group.running .theia-mobile-tool-group-meta.theia-mod-shimmer {
  background: linear-gradient(100deg,
      color-mix(in srgb, var(--theia-descriptionForeground) 78%, var(--theia-foreground)) 0%,
      var(--theia-foreground) 50%,
      color-mix(in srgb, var(--theia-descriptionForeground) 78%, var(--theia-foreground)) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: theia-mobile-agent-stream-shimmer 2.1s linear infinite;
}

@media (prefers-reduced-motion: reduce) {

  .theia-mobile-tool-group.running .theia-mobile-tool-group-verb.theia-mod-shimmer,
  .theia-mobile-tool-group.running .theia-mobile-tool-group-meta.theia-mod-shimmer {
    animation: none;
  }
}

/* ─── ToolGroup: light theme — WCAG contrast + shimmer direction fix ──────── */
/* In dark mode the shimmer "bright" peak is off-white (brightening sweep).    */
/* In light mode --theia-foreground is near-black (#111), so the bright peak   */
/* darkens instead of brightens — inverted. Fix: ink-2 base → muted peak =     */
/* lightening sweep, same visual direction as dark mode.                        */

body.qaap-theme-light .theia-mobile-tool-group-verb {
  color: var(--qaap-ink-2, #3A3A3A);
}

body.qaap-theme-light .theia-mobile-tool-group-meta {
  color: var(--qaap-ink-2, #3A3A3A);
  opacity: 0.72;
}

body.qaap-theme-light .theia-mobile-tool-group-icon {
  color: var(--qaap-ink-2, #3A3A3A);
}

body.qaap-theme-light .theia-mobile-tool-group-state {
  color: var(--qaap-muted, #8A8A8A);
}

body.qaap-theme-light .theia-mobile-tool-group-state.complete {
  color: var(--qaap-success, #357A4F);
}

body.qaap-theme-light .theia-mobile-tool-group-state.failed {
  color: var(--qaap-danger, #B23D27);
}

body.qaap-theme-light .theia-mobile-tool-group-chevron {
  color: var(--qaap-ink-2, #3A3A3A);
}

body.qaap-theme-light .theia-mobile-tool-group.running .theia-mobile-tool-group-verb.theia-mod-shimmer,
body.qaap-theme-light .theia-mobile-tool-group.running .theia-mobile-tool-group-meta.theia-mod-shimmer {
  background: linear-gradient(100deg,
      var(--qaap-ink-2, #3A3A3A) 0%,
      var(--qaap-muted, #8A8A8A) 50%,
      var(--qaap-ink-2, #3A3A3A) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: theia-mobile-agent-stream-shimmer 2.1s linear infinite;
}

.theia-mobile-tool-group-state {
  display: inline-flex;
  align-items: center;
  margin-left: auto;
  color: var(--theia-descriptionForeground);
}

.theia-mobile-tool-group-state.complete {
  color: var(--theia-charts-green);
}

.theia-mobile-tool-group-state.failed {
  color: var(--theia-errorForeground);
}

.theia-mobile-tool-group-state .codicon {
  font-size: 14px;
}

.theia-mobile-tool-group-chevron {
  color: var(--theia-descriptionForeground);
  font-size: 14px;
  opacity: 0.72;
  transition: transform 200ms ease;
}

.theia-mobile-tool-group[open] .theia-mobile-tool-group-chevron {
  transform: rotate(180deg);
}

/* ─── ToolDetails: individual tools inside an expanded group ──────────────── */
/* Non-terminal tools are plain text lines, NOT cards.                         */

.theia-mobile-tool-group-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
  /* Match summary horizontal pad; light inset keeps hierarchy without wasting width. */
  padding: 4px 8px 8px 12px;
}

.theia-mobile-tool-detail {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
}

.theia-mobile-tool-detail-detail {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-family: var(--theia-monospace-font-family);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
}

.theia-mobile-tool-detail-detail.theia-mod-file-link {
  color: var(--theia-textLink-foreground, #8ab4f8);
  cursor: pointer;
  text-decoration: none;
  text-underline-offset: 2px;
}

.theia-mobile-tool-detail-detail.theia-mod-file-link:hover,
.theia-mobile-tool-detail-detail.theia-mod-file-link:focus-visible {
  color: var(--theia-textLink-activeForeground, var(--theia-textLink-foreground, #8ab4f8));
  text-decoration: underline;
  outline: none;
}

.theia-mobile-tool-detail-file-icon {
  font-size: 14px;
  opacity: 0.72;
  flex-shrink: 0;
}

.theia-mobile-tool-detail.theia-mod-read .theia-mobile-tool-detail-file-icon {
  color: var(--theia-textLink-foreground, #8ab4f8);
  opacity: 0.95;
}

.theia-mobile-tool-detail.theia-mod-write .theia-mobile-tool-detail-file-icon {
  color: var(--theia-charts-green, #89d185);
  opacity: 0.95;
}

.theia-mobile-tool-detail.theia-mod-edit .theia-mobile-tool-detail-file-icon {
  color: var(--q-accent, #E58E40);
  opacity: 0.95;
}

.theia-mobile-tool-detail.theia-mod-delete .theia-mobile-tool-detail-file-icon {
  color: var(--theia-errorForeground, #f14c4c);
  opacity: 0.9;
}

.theia-mobile-tool-detail.theia-mod-clickable {
  cursor: pointer;
}

.theia-mobile-tool-detail.theia-mod-error .theia-mobile-tool-detail-error-icon {
  color: var(--theia-errorForeground);
  font-size: 14px;
  margin-left: auto;
}

/* ─── TerminalOutput: the only tool that gets a real card ─────────────────── */

.theia-mobile-terminal-output {
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 42%, transparent);
  border-radius: 7px;
  background: color-mix(in srgb, var(--theia-editor-background, #111) 92%, var(--theia-foreground) 4%);
  overflow: hidden;
}

.theia-mobile-terminal-output-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 0 10px;
  list-style: none;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  /* Occupy full parent width; min-width:0 lets flex children (detail) shrink */
  width: 100%;
  box-sizing: border-box;
  min-width: 0;
  /* Prefer tap→click over delayed gesture recognition on the summary chrome */
  touch-action: manipulation;
}

.theia-mobile-terminal-output-summary::-webkit-details-marker {
  display: none;
}

.theia-mobile-terminal-output-detail {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-family: var(--theia-monospace-font-family);
  /* Allow the command text to scroll horizontally without truncation */
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  white-space: nowrap;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x;
  overscroll-behavior-x: contain;
  /* Hide scrollbar track but keep scroll functional */
  scrollbar-width: none;
}

.theia-mobile-terminal-output-detail::-webkit-scrollbar {
  display: none;
}

.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-keyword {
  color: var(--theia-symbolIcon-functionForeground, #dcdcaa);
}

.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-string {
  color: var(--theia-symbolIcon-stringForeground, #ce9178);
}

.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-number {
  color: var(--theia-symbolIcon-numberForeground, #b5cea8);
}

.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-path {
  color: var(--theia-textLink-foreground, #4fc1ff);
}

.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-sep,
.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-operator {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 78%, transparent);
}

.theia-mobile-terminal-output-detail .theia-mobile-agent-token.theia-mod-comment {
  color: var(--theia-symbolIcon-keywordForeground, #6a9955);
}

.theia-mobile-terminal-output-state {
  font-size: 14px;
  margin-left: auto;
}

.theia-mobile-terminal-output.complete .theia-mobile-terminal-output-state {
  color: var(--theia-charts-green);
}

.theia-mobile-terminal-output.failed .theia-mobile-terminal-output-state {
  color: var(--theia-errorForeground);
}

.theia-mobile-terminal-output-content {
  border-top: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.24)) 36%, transparent);
  padding: 8px 10px 10px;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  overscroll-behavior-y: contain;
  max-height: 240px;
}

.theia-mobile-terminal-output-pre {
  margin: 0;
  padding: 0;
  color: color-mix(in srgb, var(--theia-foreground) 88%, var(--theia-descriptionForeground));
  font-family: var(--theia-monospace-font-family);
  font-size: 11px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}

.theia-mobile-terminal-output-code-view {
  border: 0;
  border-radius: 0;
  background: transparent;
  min-width: max-content;
}

.theia-mobile-terminal-output-code-view .theia-mobile-agent-code-line {
  padding: 0;
  gap: 10px;
}

.theia-mobile-terminal-output-code-view .theia-mobile-agent-code-gutter {
  color: color-mix(in srgb, var(--theia-descriptionForeground) 58%, transparent);
}

.theia-mobile-terminal-output-code-view .theia-mobile-agent-code-text {
  font-size: 11px;
  line-height: 1.55;
}

.theia-mobile-terminal-output-pending {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-style: italic;
  opacity: 0.7;
}

.theia-mobile-terminal-output-empty {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-style: italic;
  opacity: 0.7;
}

/* ─── Closing narrative ────────────────────────────────────────────────────── */

.theia-mobile-execution-timeline-closing {
  margin: 24px 0 0 0;
  color: var(--theia-foreground);
  font-size: 13px;
  line-height: 1.65;
}

/* ─── Closing error card: single, styled outcome for a failed turn ────────── */
/* Replaces repeated raw "Error: ..." text blocks with one compact card.      */

.theia-mobile-closing-error-card {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 24px 0 0 0;
  padding: 10px 12px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--theia-errorForeground) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--theia-errorForeground) 24%, transparent);
}

.theia-mobile-closing-error-card-icon {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--theia-errorForeground);
  font-size: 14px;
}

.theia-mobile-closing-error-card-content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}

.theia-mobile-closing-error-card-message {
  color: var(--theia-foreground);
  font-size: 13px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

/* Quiet retry action — same understated treatment as the slow-turn-hint's
   "Stop turn" button (see .theia-mobile-slow-turn-hint-stop). */
.theia-mobile-closing-error-card-retry {
  flex-shrink: 0;
  padding: 2px 8px;
  border: 1px solid var(--theia-panel-border, rgba(128, 128, 128, 0.35));
  border-radius: 6px;
  background: transparent;
  color: var(--theia-foreground);
  font-size: 11px;
  line-height: 1.4;
  cursor: pointer;
}

.theia-mobile-closing-error-card-retry:hover,
.theia-mobile-closing-error-card-retry:focus-visible {
  background: var(--theia-toolbar-hoverBackground);
  outline: none;
}

.theia-mobile-closing-error-card-retry:disabled {
  opacity: 0.5;
  cursor: default;
}

/* ─── DiffSummary: the natural closing of the execution story ─────────────── */

.theia-mobile-diff-summary {
  margin-top: 24px;
  padding: 14px 8px 4px 8px;
  border-top: 1px solid color-mix(in srgb, var(--theia-foreground) 10%, transparent);
}

/* Files-changed card — matches the Codex-style “N Files Changed / Review” panel. */
.theia-mobile-diff-summary.theia-mod-files {
  box-sizing: border-box;
  margin-top: 20px;
  padding: 16px 16px 12px;
  border: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.35)) 85%, transparent);
  border-radius: 16px;
  border-top: 1px solid color-mix(in srgb, var(--theia-panel-border, rgba(128, 128, 128, 0.35)) 85%, transparent);
  background: color-mix(in srgb, var(--theia-editorWidget-background, #1e1e1e) 92%, #000);
}

.theia-mobile-diff-summary-header {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 28px;
  flex-wrap: wrap;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-header {
  justify-content: space-between;
  flex-wrap: nowrap;
  gap: 12px;
  min-height: 22px;
  margin-bottom: 10px;
}

.theia-mobile-diff-summary-icon {
  color: var(--theia-descriptionForeground);
  font-size: 14px;
}

.theia-mobile-diff-summary-title {
  font-weight: 500;
  font-size: 13px;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-title {
  flex: 1 1 auto;
  min-width: 0;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 88%, var(--theia-foreground));
  font-size: 13px;
  font-weight: 500;
  line-height: 1.3;
}

.theia-mobile-diff-summary-review {
  flex: none;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  color: color-mix(in srgb, var(--theia-descriptionForeground) 78%, transparent);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.3;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.theia-mobile-diff-summary-review:hover,
.theia-mobile-diff-summary-review:focus-visible {
  color: var(--theia-foreground);
}

.theia-mobile-diff-summary-stat {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
}

.theia-mobile-diff-summary-stat.theia-mod-added {
  color: var(--theia-charts-green);
}

.theia-mobile-diff-summary-stat.theia-mod-deleted {
  color: var(--theia-errorForeground);
}

.theia-mobile-diff-summary-files {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 8px;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-files {
  gap: 2px;
  margin-top: 0;
}

.theia-mobile-diff-summary-file {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 24px;
  color: var(--theia-descriptionForeground);
  font-size: 12px;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-file {
  min-height: 28px;
  gap: 10px;
}

.theia-mobile-diff-summary-file-main {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-file-main {
  gap: 8px;
}

.theia-mobile-diff-summary-file-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-file-name {
  color: color-mix(in srgb, var(--theia-foreground) 92%, var(--theia-descriptionForeground));
  font-size: 13px;
  font-weight: 400;
  line-height: 1.3;
}

.theia-mobile-diff-summary-file-icon {
  font-size: 14px;
  opacity: 0.72;
  flex-shrink: 0;
}

.theia-mobile-diff-summary-file-badge {
  flex: none;
  min-width: 1.4em;
  color: color-mix(in srgb, #6b8cae 82%, var(--theia-descriptionForeground));
  font-family: var(--theia-ui-font-family, system-ui, sans-serif);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1;
  text-align: center;
}

.theia-mobile-diff-summary-file-tail {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  flex: none;
  min-width: 0;
  font-variant-numeric: tabular-nums;
}

.theia-mobile-diff-summary-file-stat {
  font-size: 11px;
  flex-shrink: 0;
}

.theia-mobile-diff-summary.theia-mod-files .theia-mobile-diff-summary-file-stat {
  font-size: 12px;
  font-weight: 500;
}

.theia-mobile-diff-summary-file-stat.theia-mod-added {
  color: color-mix(in srgb, var(--theia-charts-green, #73c991) 88%, #9ccc65);
}

.theia-mobile-diff-summary-file-stat.theia-mod-deleted {
  color: color-mix(in srgb, var(--theia-errorForeground, #f48771) 85%, #e57373);
}

.theia-mobile-diff-summary-file-type,
.theia-mobile-diff-summary-more {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  flex-shrink: 0;
}

.theia-mobile-diff-summary-file-type.theia-mod-add {
  color: var(--theia-charts-green);
}

.theia-mobile-diff-summary-file-type.theia-mod-delete {
  color: var(--theia-errorForeground);
}

/* ---- Transcript images: chat-style thumbnails + full-page lightbox ---------------------- */

/* Images inside transcript messages (visual evidence, pasted screenshots) render as bounded
   thumbnails like any chat app; tapping opens the lightbox below. */
.theia-mobile-agent-transcript-content img {
  display: block;
  max-width: min(300px, 100%);
  max-height: 220px;
  width: auto;
  height: auto;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border);
  cursor: zoom-in;
  margin: 6px 0;
}

.qaap-transcript-image-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(0, 0, 0, 0.88);
}

.qaap-transcript-image-lightbox img {
  max-width: 100%;
  max-height: 100%;
  border-radius: 8px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.6);
  cursor: default;
}

.qaap-transcript-image-lightbox-close {
  position: absolute;
  top: calc(env(safe-area-inset-top, 0px) + 14px);
  right: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  cursor: pointer;
}

.qaap-transcript-image-lightbox-close:hover {
  background: rgba(255, 255, 255, 0.26);
}

.qaap-transcript-image-lightbox-close .codicon {
  font-size: 20px;
}

/* Inline chat-style player for recorded visual evidence (`[QAAP record]`). Native controls
   provide play/pause and fullscreen. */
.qaap-transcript-video-evidence {
  display: block;
  max-width: min(340px, 100%);
  max-height: 260px;
  border-radius: 10px;
  border: 1px solid var(--theia-widget-border);
  background: #000;
  margin: 6px 0;
}

/* Pending visual evidence while `[QAAP capture]` / `[QAAP record]` is being processed. */
.theia-mobile-agent-transcript-capture-directive {
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  font-family: var(--monaco-monospace-font, ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace);
  letter-spacing: 0.01em;
  margin-bottom: 4px;
}

.theia-mobile-agent-transcript-capture-pending {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: min(300px, 100%);
  margin: 4px 0 10px;
}

.theia-mobile-agent-transcript-capture-pending-preview {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  background: color-mix(in srgb, var(--theia-foreground) 6%, transparent);
  box-shadow: 0 4px 14px color-mix(in srgb, #000 12%, transparent);
}

.theia-mobile-agent-transcript-capture-pending-preview::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg,
      color-mix(in srgb, var(--theia-foreground) 4%, transparent) 8%,
      color-mix(in srgb, var(--theia-foreground) 12%, transparent) 18%,
      color-mix(in srgb, var(--theia-foreground) 4%, transparent) 33%);
  background-size: 200% 100%;
  animation: qaap-sticky-image-preview-shimmer 1.1s ease-in-out infinite;
  pointer-events: none;
}

.theia-mobile-agent-transcript-capture-pending-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  padding: 0 2px;
  color: var(--theia-descriptionForeground);
  font-size: 12px;
  line-height: 1.35;
}

.theia-mobile-agent-transcript-capture-pending-icon {
  flex: 0 0 auto;
  font-size: 14px;
  color: var(--theia-icon-foreground);
}

.theia-mobile-agent-transcript-capture-pending-label {
  flex: 1 1 auto;
  min-width: 0;
}

.theia-mobile-agent-transcript-capture-pending-routes {
  flex: 0 0 auto;
  padding: 2px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--theia-foreground) 8%, transparent);
  color: var(--theia-foreground);
  font-family: var(--monaco-monospace-font, ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace);
  font-size: 11px;
}

.theia-mobile-agent-transcript-capture-pending.theia-mod-video .theia-mobile-agent-transcript-capture-pending-preview {
  aspect-ratio: 16 / 9;
}

@media (prefers-reduced-motion: reduce) {
  .theia-mobile-agent-transcript-capture-pending-preview::after {
    animation: none;
    background: color-mix(in srgb, var(--theia-foreground) 8%, transparent);
  }
}

/* ─── Premium Web Search card (transcript) ─────────────────────────────────── */

.theia-mobile-agent-web-search {
  --qaap-ws-text: var(--theia-foreground);
  --qaap-ws-muted: var(--theia-descriptionForeground);
  --qaap-ws-subtle: color-mix(in srgb, var(--theia-descriptionForeground) 78%, transparent);
  --qaap-ws-border: color-mix(in srgb, var(--theia-widget-border, var(--theia-border-color, #e6e8ec)) 88%, transparent);
  --qaap-ws-success: #15a06a;
  --qaap-ws-success-soft: rgba(21, 160, 106, 0.16);
  --qaap-ws-ease: cubic-bezier(0.32, 0.72, 0, 1);
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  font-size: 13px;
  line-height: 1.4;
  color: var(--qaap-ws-text);
}

body.theia-dark .theia-mobile-agent-web-search,
.theia-dark .theia-mobile-agent-web-search {
  --qaap-ws-success: #34d399;
  --qaap-ws-success-soft: rgba(52, 211, 153, 0.16);
}

.theia-mobile-tool-group.theia-mod-web-search {
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 4px 0 8px;
}

.theia-mobile-tool-group.theia-mod-web-search:hover {
  background: transparent;
}

.theia-mobile-tool-group.theia-mod-web-search>.theia-mobile-tool-group-summary.theia-mod-web-search-hidden {
  display: none !important;
}

.theia-mobile-tool-group.theia-mod-web-search>.theia-mobile-tool-group-details {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0;
  margin: 0;
  border: none;
}

.theia-mobile-tool-group-details>.theia-mobile-agent-web-search {
  margin: 0;
  padding: 0;
}

.theia-mobile-agent-web-search-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 20px;
  min-width: 0;
}

.theia-mobile-agent-web-search-row>svg {
  flex: none;
  color: var(--qaap-ws-muted);
  margin-left: -1px;
}

.theia-mobile-agent-web-search-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 550;
  color: var(--qaap-ws-text);
  white-space: nowrap;
  min-width: 0;
}

.theia-mobile-agent-web-search-quote {
  overflow: hidden;
  text-overflow: ellipsis;
}

.theia-mobile-agent-web-search-shimmer {
  overflow: hidden;
  text-overflow: ellipsis;
  background: linear-gradient(90deg,
      color-mix(in srgb, var(--qaap-ws-text) 45%, transparent) 0%,
      var(--qaap-ws-text) 44%,
      color-mix(in srgb, var(--qaap-ws-text) 45%, transparent) 80%);
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  animation: theia-mobile-agent-web-search-shimmer 2.7s linear infinite;
}

.theia-mobile-agent-web-search-shimmer.theia-mod-done {
  animation: none;
  background: none;
  -webkit-text-fill-color: var(--qaap-ws-text);
  color: var(--qaap-ws-text);
}

.theia-mobile-agent-web-search-chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex: none;
  border: none;
  padding: 0;
  background: none;
  color: var(--qaap-ws-subtle);
  cursor: pointer;
  border-radius: 4px;
  transition: color 0.16s var(--qaap-ws-ease), transform 0.28s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-chevron:hover {
  color: var(--qaap-ws-muted);
}

.theia-mobile-agent-web-search-chevron[aria-expanded="false"] {
  transform: rotate(180deg);
}

.theia-mobile-agent-web-search-collapsible {
  display: grid;
  grid-template-rows: 1fr;
  opacity: 1;
  transition: grid-template-rows 0.32s var(--qaap-ws-ease), opacity 0.22s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-collapsible.theia-mod-collapsed {
  grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
}

.theia-mobile-agent-web-search-collapsible-inner {
  min-height: 0;
  overflow: hidden;
}

.theia-mobile-agent-web-search-results {
  position: relative;
  display: flex;
  gap: 6px;
  align-items: stretch;
}

.theia-mobile-agent-web-search-rail {
  flex: none;
  width: 1px;
  align-self: stretch;
  border-left: 1px solid var(--qaap-ws-border);
  margin-left: 5.5px;
}

.theia-mobile-agent-web-search-list {
  flex: 1;
  list-style: none;
  margin: 0;
  padding: 4px 0 2px 6px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.theia-mobile-agent-web-search-site {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  line-height: 18px;
  color: var(--qaap-ws-muted);
  min-width: 0;
  opacity: 0;
  transform: translateY(4px);
  animation: theia-mobile-agent-web-search-enter 0.34s var(--qaap-ws-ease) forwards;
}

.theia-mobile-agent-web-search-site[data-state="done"] {
  cursor: pointer;
}

.theia-mobile-agent-web-search-bullet {
  position: relative;
  width: 12px;
  height: 12px;
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.theia-mobile-agent-web-search-dots,
.theia-mobile-agent-web-search-globe,
.theia-mobile-agent-web-search-check {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.theia-mobile-agent-web-search-dots {
  color: var(--qaap-ws-subtle);
  opacity: 1;
  transition: opacity 0.32s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-site[data-state="loading"] .theia-mobile-agent-web-search-dots,
.theia-mobile-agent-web-search-site[data-state="done"] .theia-mobile-agent-web-search-dots {
  opacity: 0;
}

.theia-mobile-agent-web-search-globe {
  color: var(--qaap-ws-subtle);
  opacity: 0;
  transform: scale(0.88);
  transition: opacity 0.32s var(--qaap-ws-ease), transform 0.36s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-globe svg {
  overflow: visible;
  display: block;
}

.theia-mobile-agent-web-search-site[data-state="loading"] .theia-mobile-agent-web-search-globe {
  opacity: 1;
  transform: scale(1);
}

.theia-mobile-agent-web-search-site[data-state="done"] .theia-mobile-agent-web-search-globe {
  opacity: 0;
  transform: scale(0.775);
  transition: opacity 0.22s var(--qaap-ws-ease), transform 0.26s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-check {
  color: var(--qaap-ws-success);
  opacity: 0;
  transform: scale(1.175);
  transition: opacity 0.24s var(--qaap-ws-ease) 0.06s, transform 0.28s var(--qaap-ws-ease) 0.06s;
}

.theia-mobile-agent-web-search-site[data-state="done"] .theia-mobile-agent-web-search-check {
  opacity: 1;
  transform: scale(1);
}

.theia-mobile-agent-web-search-title {
  color: var(--qaap-ws-text);
  font-weight: 450;
  white-space: nowrap;
  flex: none;
}

.theia-mobile-agent-web-search-site[data-state="pending"] .theia-mobile-agent-web-search-title {
  color: var(--qaap-ws-muted);
}

.theia-mobile-agent-web-search-site[data-state="loading"] .theia-mobile-agent-web-search-title {
  background: linear-gradient(90deg,
      color-mix(in srgb, var(--qaap-ws-text) 50%, transparent) 0%,
      var(--qaap-ws-text) 44%,
      color-mix(in srgb, var(--qaap-ws-text) 50%, transparent) 80%);
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  animation: theia-mobile-agent-web-search-shimmer 2.7s linear infinite;
}

.theia-mobile-agent-web-search-sep {
  color: var(--qaap-ws-subtle);
  flex: none;
}

.theia-mobile-agent-web-search-url {
  color: var(--qaap-ws-muted);
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: color 0.16s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-arrow {
  display: inline-flex;
  flex: none;
  color: var(--qaap-ws-subtle);
  margin-left: -2px;
  opacity: 0;
  transform: rotate(45deg) translate(0, 2px);
  transition: opacity 0.16s var(--qaap-ws-ease), transform 0.22s var(--qaap-ws-ease);
}

.theia-mobile-agent-web-search-site[data-state="done"]:hover .theia-mobile-agent-web-search-arrow {
  opacity: 1;
  transform: rotate(45deg) translate(0, 0);
}

.theia-mobile-agent-web-search-site[data-state="done"]:hover .theia-mobile-agent-web-search-url {
  color: var(--qaap-ws-text);
}

@keyframes theia-mobile-agent-web-search-shimmer {
  0% {
    background-position: -200% 0;
  }

  100% {
    background-position: 200% 0;
  }
}

@keyframes theia-mobile-agent-web-search-enter {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {

  .theia-mobile-agent-web-search-shimmer,
  .theia-mobile-agent-web-search-site[data-state="loading"] .theia-mobile-agent-web-search-title {
    animation: none;
    background: none;
    -webkit-text-fill-color: var(--qaap-ws-text);
    color: var(--qaap-ws-text);
  }

  .theia-mobile-agent-web-search-site {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

/*
 * Queued follow-ups painted at the transcript tail (see qaap-transcript-queued-bubbles.ts).
 * Same user bubble, held back visually: the message is sent but not yet in the turn.
 */
.theia-mobile-agent-transcript-queued {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  width: 100%;
}

.theia-mobile-agent-transcript-msg.theia-mod-user.theia-mod-queued {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  opacity: 0.62;
  border-style: dashed;
}

.theia-mobile-agent-transcript-msg.theia-mod-user.theia-mod-queued .theia-mobile-agent-transcript-content {
  align-self: stretch;
}

.theia-mobile-agent-transcript-queued-tag {
  flex: 0 0 auto;
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 3px 6px;
  border-radius: var(--qaap-mobile-radius-control, 8px);
  background: color-mix(in srgb, var(--theia-foreground) 12%, transparent);
  color: var(--theia-descriptionForeground, var(--theia-foreground));
  white-space: nowrap;
}

/*
 * Per-run stop in the process accordion header (see qaap-execution-event-timeline.ts).
 * A session can run several agents at once, so each working turn stops on its own; the
 * composer Stop remains the session-wide one.
 */
.theia-mobile-process-accordion-run-stop {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin-left: auto;
  padding: 0;
  border-radius: var(--qaap-mobile-radius-control, 8px);
  border: 1px solid color-mix(in srgb, var(--theia-foreground) 18%, transparent);
  background: transparent;
  color: var(--theia-descriptionForeground);
  cursor: pointer;
  flex: 0 0 auto;
}

.theia-mobile-process-accordion-run-stop .codicon {
  font-size: 11px;
}

.theia-mobile-process-accordion-run-stop:hover,
.theia-mobile-process-accordion-run-stop:focus-visible {
  color: var(--theia-errorForeground, #e06c75);
  border-color: color-mix(in srgb, var(--theia-errorForeground, #e06c75) 45%, transparent);
}

.theia-mobile-process-accordion-run-stop:focus-visible {
  outline: 1px solid var(--theia-focusBorder, #007fd4);
  outline-offset: 2px;
}

.theia-mobile-process-accordion-run-stop+.theia-mobile-process-accordion-chevron {
  margin-left: 8px;
}

/* === Mobile IDE chrome: hidden on narrow viewport (IDE is desktop-only) === */
/* The bottom bar, side sheets, overlay host, and workbench top bar are IDE-only chrome.
   On narrow viewports the user never enters the IDE, so these elements are never needed.
   Hiding them via CSS avoids rendering overhead and prevents any flash of IDE chrome. */
@media (max-width: 767px),
(pointer: coarse) {

  .theia-mobile-bottom-chrome-host,
  .theia-mobile-bottom-chrome-host>#theia-mobile-bottom-bar,
  .theia-mobile-bottom-chrome-host>#theia-statusBar,
  .theia-mobile-bottom-activity-bar,
  .theia-mobile-side-sheet,
  .theia-mobile-overlay-host,
  .theia-mobile-workbench-top-bar:not([data-qaap-work-hub-top-bar]),
  .theia-mobile-bottom-split-panel {
    display: none !important;
  }
}

/* ---------------------------------------------------------------------------
   Composer drag-and-drop — the composer itself morphs (no external overlay)
   ------------------------------------------------------------------------- */

/* Drag-over: the input panel gets a dashed accent border, glow, and tint */
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drag-over {
  border-color: color-mix(in srgb, var(--theia-focus-border, #007fd4) 65%, transparent) !important;
  border-style: dashed !important;
  border-width: 2px !important;
  background: color-mix(in srgb, var(--theia-focus-border, #007fd4) 10%, var(--theia-editor-background)) !important;
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--theia-focus-border, #007fd4) 18%, transparent),
    0 8px 28px color-mix(in srgb, var(--theia-focus-border, #007fd4) 20%, transparent) !important;
  transform: scale(1.015);
  transition: border-color 140ms ease, box-shadow 140ms ease, background 140ms ease, transform 140ms ease;
  animation: qaap-composer-drop-breathe 1.8s ease-in-out infinite;
}

@keyframes qaap-composer-drop-breathe {

  0%,
  100% {
    box-shadow:
      0 0 0 3px color-mix(in srgb, var(--theia-focus-border, #007fd4) 14%, transparent),
      0 8px 28px color-mix(in srgb, var(--theia-focus-border, #007fd4) 16%, transparent);
  }

  50% {
    box-shadow:
      0 0 0 5px color-mix(in srgb, var(--theia-focus-border, #007fd4) 22%, transparent),
      0 8px 36px color-mix(in srgb, var(--theia-focus-border, #007fd4) 28%, transparent);
  }
}

/* Dim the textarea + controls while dragging files over */
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input,
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input-editor,
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drag-over .theia-mobile-projects-sticky-composer-controls-row,
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input-actions {
  opacity: 0.3;
  pointer-events: none;
  transition: opacity 140ms ease;
}

/* Placeholder text gets the accent color during drag-over */
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input::placeholder {
  color: color-mix(in srgb, var(--theia-focus-border, #007fd4) 90%, var(--theia-foreground));
  font-weight: 600;
  transition: color 140ms ease;
}

/* Loading shimmer after drop — the composer "absorbs" the file */
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drop-loading {
  position: relative;
  overflow: hidden;
}

.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-drop-loading::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  background: linear-gradient(100deg,
      transparent 20%,
      color-mix(in srgb, var(--theia-focus-border, #007fd4) 22%, transparent) 50%,
      transparent 80%);
  background-size: 200% 100%;
  animation: qaap-composer-drop-shimmer 900ms ease-out;
  border-radius: inherit;
}

@keyframes qaap-composer-drop-shimmer {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}

/* ---------------------------------------------------------------------------
   Card-level drag-over — the entire composer card is the drop target
   ------------------------------------------------------------------------- */

/* Drag-over on the whole card: dashed accent border, glow, and tint */
.theia-mobile-projects-sticky-composer-card.theia-mod-drag-over {
  border-color: color-mix(in srgb, var(--theia-focus-border, #007fd4) 65%, transparent) !important;
  border-style: dashed !important;
  border-width: 2px !important;
  background: color-mix(in srgb, var(--theia-focus-border, #007fd4) 8%, var(--theia-editor-background)) !important;
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--theia-focus-border, #007fd4) 18%, transparent),
    0 8px 28px color-mix(in srgb, var(--theia-focus-border, #007fd4) 20%, transparent) !important;
  transition: border-color 140ms ease, box-shadow 140ms ease, background 140ms ease;
  animation: qaap-composer-drop-breathe 1.8s ease-in-out infinite;
}

/* Dim the inner input panel content while dragging files over the card */
.theia-mobile-projects-sticky-composer-card.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input,
.theia-mobile-projects-sticky-composer-card.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input-editor,
.theia-mobile-projects-sticky-composer-card.theia-mod-drag-over .theia-mobile-projects-sticky-composer-controls-row,
.theia-mobile-projects-sticky-composer-card.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input-actions {
  opacity: 0.3;
  transition: opacity 140ms ease;
}

/* Placeholder text gets the accent color during card-level drag-over */
.theia-mobile-projects-sticky-composer-card.theia-mod-drag-over .theia-mobile-projects-sticky-composer-input::placeholder {
  color: color-mix(in srgb, var(--theia-focus-border, #007fd4) 90%, var(--theia-foreground));
  font-weight: 600;
  transition: color 140ms ease;
}

/* ---------------------------------------------------------------------------
   Absorption animation — ghost pill flies from drop point to attachment carousel
   ------------------------------------------------------------------------- */

.qaap-composer-absorption-ghost {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--theia-focus-border, #007fd4) 85%, var(--theia-editor-background));
  color: var(--theia-editor-background);
  font-size: 18px;
  box-shadow:
    0 4px 16px color-mix(in srgb, var(--theia-focus-border, #007fd4) 40%, transparent),
    0 0 0 3px color-mix(in srgb, var(--theia-focus-border, #007fd4) 25%, transparent);
}

.qaap-composer-absorption-ghost .codicon {
  font-size: 18px;
  color: #fff;
}

.qaap-composer-absorption-ghost-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: var(--theia-focus-border, #007fd4);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  line-height: 16px;
  text-align: center;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
}

/* Bounce on the attachment carousel / input panel when the ghost arrives */
.theia-mobile-projects-sticky-composer-context-images.theia-mod-absorb-bounce,
.theia-mobile-projects-sticky-composer-input-wrap.theia-mod-absorb-bounce {
  animation: qaap-composer-absorb-bounce 500ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes qaap-composer-absorb-bounce {
  0% {
    transform: scale(1);
  }

  30% {
    transform: scale(1.06);
  }

  50% {
    transform: scale(0.97);
  }

  70% {
    transform: scale(1.03);
  }

  100% {
    transform: scale(1);
  }
}
